def _database_location(database_url: str) -> str:
    """Return a non-sensitive database location for UI/status output."""
    if not database_url:
        return ''
    try:
        from urllib.parse import urlparse
        parsed = urlparse(database_url)
        host = parsed.hostname or ''
        port = f':{parsed.port}' if parsed.port else ''
        name = parsed.path.lstrip('/')
        return f'{parsed.scheme}://{host}{port}/{name}' if host else parsed.scheme
    except Exception:
        return 'configured'


def _now_iso() -> str:
    return datetime.datetime.now(datetime.timezone.utc).strftime('%Y-%m-%dT%H:%M:%S.%f') + 'Z'


def _resolve_ztf_main(ztf_path: str | Path) -> Path | None:
    """Return the legacy ZeroTouch Framework 1.x entrypoint."""
    root = Path(ztf_path)
    candidate = root / 'main.py'
    if candidate.exists():
        return candidate
    return None


def _ztf_installed(ztf_path: str | Path) -> bool:
    return _resolve_ztf_main(ztf_path) is not None


def _ztf_detect(ztf_path: str | Path) -> dict:
    root = Path(ztf_path)
    legacy_main = root / 'main.py'
    package_main = root / 'ztf' / 'main.py'
    pyproject = root / 'pyproject.toml'

    if legacy_main.exists():
        return {
            'installed': True,
            'compatible': True,
            'layout': 'legacy-1.x',
            'entrypoint': str(legacy_main),
            'requiredRef': ZTF_LEGACY_REF,
            'message': 'Legacy ZTF 1.x workflow/script CLI detected',
        }
    if package_main.exists() or pyproject.exists():
        return {
            'installed': True,
            'compatible': False,
            'layout': 'ztf-2.x',
            'entrypoint': str(package_main) if package_main.exists() else '',
            'requiredRef': ZTF_LEGACY_REF,
            'message': (
                'ZTF 2.x detected. ZTF-Orchestrator legacy workflows require '
                f'ZeroTouch Framework {ZTF_LEGACY_REF} or the 1.x branch.'
            ),
        }
    return {
        'installed': False,
        'compatible': False,
        'layout': 'missing',
        'entrypoint': '',
        'requiredRef': ZTF_LEGACY_REF,
        'message': 'ZeroTouch Framework was not found',
    }


def _ztf2_detect(ztf2_path: str | Path, ztf2_command: str = ZTF2_COMMAND_DEFAULT) -> dict:
    root = Path(ztf2_path)
    package_dir = root / 'ztf'
    pyproject = root / 'pyproject.toml'
    legacy_main = root / 'main.py'
    if package_dir.exists() and pyproject.exists() and not legacy_main.exists():
        return {
            'installed': True,
            'compatible': True,
            'layout': 'ztf-2.x',
            'entrypoint': ztf2_command,
            'requiredRef': ZTF2_REF,
            'message': 'ZTF 2.x plan/apply CLI layout detected',
        }
    if legacy_main.exists():
        return {
            'installed': True,
            'compatible': False,
            'layout': 'legacy-1.x',
            'entrypoint': str(legacy_main),
            'requiredRef': ZTF2_REF,
            'message': f'Legacy ZTF 1.x detected. ZTF 2.x mode requires {ZTF2_REF} or a reviewed 2.x checkout.',
        }
    if root.exists():
        return {
            'installed': False,
            'compatible': False,
            'layout': 'unknown',
            'entrypoint': '',
            'requiredRef': ZTF2_REF,
            'message': 'ZTF 2.x package layout was not found',
        }
    return {
        'installed': False,
        'compatible': False,
        'layout': 'missing',
        'entrypoint': '',
        'requiredRef': ZTF2_REF,
        'message': 'ZTF 2.x runtime path was not found',
    }


def _ztf_incompatible_error(ztf_path: str | Path) -> tuple[dict, int] | None:
    info = _ztf_detect(ztf_path)
    if info.get('compatible'):
        return None
    return {
        'error': info['message'],
        'ztf': info,
    }, 409


def _ztf_requirements_file(ztf_path: str | Path) -> str | None:
    root = Path(ztf_path)
    candidates = ['requirements/requirements.txt', 'requirements.txt']
    req_dir = root / 'requirements'
    if req_dir.is_dir():
        for path in sorted(req_dir.glob('*.txt')):
            candidates.insert(0, str(path.relative_to(root)))
    for candidate in candidates:
        if (root / candidate).exists():
            return candidate
    return None


def _is_git_checkout(path: str | Path) -> bool:
    try:
        result = subprocess.run(
            ['git', '-C', str(path), 'rev-parse', '--is-inside-work-tree'],
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True,
            timeout=10,
        )
        return result.returncode == 0 and result.stdout.strip() == 'true'
    except Exception:
        return False


def _ztf2_install_python(ztf2_command: str, bootstrap_python: str) -> tuple[str, Path | None]:
    """Resolve the Python executable used to install the ZTF 2.x CLI."""
    command = Path(ztf2_command)
    if not command.is_absolute():
        return bootstrap_python, None
    if command.parent.name.lower() not in {'bin', 'scripts'}:
        return bootstrap_python, None
    venv_root = command.parent.parent
    python_name = 'python.exe' if os.name == 'nt' or command.parent.name.lower() == 'scripts' else 'python'
    return str(venv_root / command.parent.name / python_name), venv_root


def _path_has_entries(path: Path) -> bool:
    try:
        next(path.iterdir())
        return True
    except StopIteration:
        return False
    except OSError:
        return True


def _ztf_main_arg(ztf_path: str | Path) -> str:
    main = _resolve_ztf_main(ztf_path)
    if main is None:
        return 'main.py'
    try:
        return str(main.relative_to(Path(ztf_path)))
    except ValueError:
        return str(main)


def _nkp_script(nkp_path: str | Path) -> Path | None:
    root = Path(nkp_path)
    candidates = (
        [root / 'scripts' / 'zt.ps1', root / 'scripts' / 'zt.sh']
        if os.name == 'nt'
        else [root / 'scripts' / 'zt.sh', root / 'scripts' / 'zt.ps1']
    )
    return next((candidate for candidate in candidates if candidate.exists()), None)


def _nkp_installed(nkp_path: str | Path) -> bool:
    return _nkp_script(nkp_path) is not None


def _parse_iso_datetime(value: str | None):
    if not value:
        return None
    try:
        return datetime.datetime.fromisoformat(str(value).replace('Z', '+00:00'))
    except (TypeError, ValueError):
        return None


def _artifact_status(record: dict) -> str:
    verified_at = _parse_iso_datetime(record.get('verifiedAt'))
    expires_at = _parse_iso_datetime(record.get('expiresAt'))
    now = datetime.datetime.now(datetime.timezone.utc)
    if verified_at:
        return 'verified'
    if expires_at and expires_at < now:
        return 'expired'
    if expires_at and expires_at - now <= datetime.timedelta(days=14):
        return 'expiring'
    if record.get('archiveLocation'):
        return 'archived'
    return 'pending'


def _load_appliance_artifacts() -> list[dict]:
    artifacts = read_json(APPLIANCE_ARTIFACTS_FILE, [])
    if not isinstance(artifacts, list):
        return []
    normalized = []
    for item in artifacts:
        if not isinstance(item, dict) or not item.get('id'):
            continue
        record = dict(item)
        record['status'] = _artifact_status(record)
        normalized.append(record)
