def _redact_command_output(text: str) -> str:
    value = str(text or '')
    value = re.sub(r'(?i)(password|token|secret|apikey|api_key)\s*[:=]\s*\S+', r'\1=<redacted>', value)
    value = re.sub(r'postgresql://([^:\s/]+):([^@\s]+)@', r'postgresql://\1:<redacted>@', value)
    return value[:12000]


def _sha256_text(text: str) -> str:
    return hashlib.sha256(str(text or '').encode('utf-8')).hexdigest()


def _evidence_summary_status(readiness: dict, compatibility: dict | None, schema_validation: dict | None = None) -> str:
    if readiness.get('status') == 'blocked':
        return 'blocked'
    if compatibility and compatibility.get('status') == 'blocked':
        return 'blocked'
    if schema_validation and schema_validation.get('status') == 'fail':
        return 'blocked'
    if readiness.get('status') == 'needs_attention' or (compatibility and compatibility.get('status') == 'needs_review'):
        return 'needs_review'
    if schema_validation and schema_validation.get('status') == 'warn':
        return 'needs_review'
    return 'ready'


def _workflow_evidence_readiness(config_content: str, config_file: str, job: dict | None, workflow: str) -> dict:
    checks = []

    def add_check(check_id: str, label: str, status: str, detail: str) -> None:
        checks.append({'id': check_id, 'label': label, 'status': status, 'detail': detail})

    parsed, parse_error = _parse_structured_config(config_content, config_file)
    if config_content:
        add_check(
            'config_parse',
            'Config parses',
            'fail' if parse_error else 'pass',
            parse_error or 'YAML/JSON content parsed successfully',
        )
    else:
        add_check('config_present', 'Config present', 'warn', 'No config content is attached to this evidence record')

    if config_file:
        add_check('config_file', 'Config file named', 'pass', config_file)
    else:
        add_check('config_file', 'Config file named', 'warn', 'No config filename was recorded')

    if workflow in ALLOWED_WORKFLOWS:
        add_check('workflow_allowlist', 'Workflow allowlisted', 'pass', workflow)
    elif workflow:
        add_check('workflow_allowlist', 'Workflow allowlisted', 'warn', 'Record is for a script or external workflow identifier')
    else:
        add_check('workflow_allowlist', 'Workflow allowlisted', 'warn', 'No workflow identifier was supplied')

    if job:
        job_status = job.get('status') or 'unknown'
        add_check(
            'job_terminal',
            'Execution job terminal',
            'pass' if job_status == 'success' else 'warn' if job_status in ExecutionJobManager.TERMINAL else 'fail',
            f'Job {job.get("id")} status is {job_status}',
        )
    else:
        add_check('job_terminal', 'Execution job terminal', 'warn', 'No execution job was linked')

    failed = sum(1 for item in checks if item['status'] == 'fail')
    warnings = sum(1 for item in checks if item['status'] == 'warn')
    total = len(checks) or 1
    return {
        'status': 'blocked' if failed else 'needs_attention' if warnings else 'ready',
        'score': round(((total - failed - (warnings * 0.5)) / total) * 100),
        'summary': {
            'passed': sum(1 for item in checks if item['status'] == 'pass'),
            'warnings': warnings,
            'failed': failed,
        },
        'checks': checks,
    }


def _build_workflow_validation_evidence(data: dict, user: str) -> dict:
    job_id = str(data.get('jobId') or '').strip()
    job = None
    execution = None
    if job_id:
        job = next((item for item in _job_manager._load_jobs() if item.get('id') == job_id), None)
        if not job:
            history = read_json(HISTORY_FILE, [])
            if isinstance(history, list):
                execution = next((item for item in history if isinstance(item, dict) and item.get('id') == job_id), None)
    if job_id and not job and not execution:
        raise ValueError('Execution job or history record was not found')

    workflow = str(data.get('workflow') or '').strip()
    config_file = str(data.get('configFile') or '').strip()
    config_content = ''
    approval_id = str(data.get('approvalId') or '').strip()
    execution_status = ''
    return_code = None
    task_ids = data.get('taskIds', []) if isinstance(data.get('taskIds'), list) else []
    output_excerpt = _redact_command_output(data.get('output') or '')

    if job:
        workflow = workflow or str(job.get('workflow') or '').strip()
        payload = job.get('payload') if isinstance(job.get('payload'), dict) else {}
        trace = job.get('trace') if isinstance(job.get('trace'), dict) else {}
        config_file = config_file or str(trace.get('configFile') or payload.get('configFile') or '').strip()
        config_content = str(payload.get('configContent') or '')
        approval_id = approval_id or str(trace.get('approvalId') or payload.get('approvalId') or '').strip()
        execution_status = str(job.get('status') or '')
        return_code = job.get('returnCode')
        task_ids = job.get('taskIds', task_ids)
        if not output_excerpt:
            output_excerpt = _redact_command_output('\n'.join(
                str(event.get('data') or '') for event in job.get('logs', [])[-120:]
            ))

    if execution:
        workflow = workflow or str(execution.get('workflow') or '').strip()
        config_file = config_file or str(execution.get('configFile') or '').strip()
        config_content = config_content or str(execution.get('configContent') or '')
        execution_status = execution_status or str(execution.get('status') or '')
        return_code = return_code if return_code is not None else execution.get('returnCode')
        if not output_excerpt:
            output_excerpt = _redact_command_output('\n'.join([
                str(execution.get('stdout') or ''),
                str(execution.get('stderr') or ''),
            ]).strip())

    if not config_content and data.get('configContent'):
        config_content = str(data.get('configContent') or '')

    if not config_content and config_file:
        path = safe_config_path(config_file, get_configs_dir())
        if path and path.exists():
            config_content = path.read_text(encoding='utf-8')

    if not config_content:
        raise ValueError('workflow evidence requires jobId, configFile, or configContent')

    readiness = _workflow_evidence_readiness(config_content, config_file, job, workflow)
    parsed, parse_error = _parse_structured_config(config_content, config_file)
    schema_validation = {
        'status': 'fail' if parse_error else 'pass',
        'missing': [],
        'warnings': [parse_error] if parse_error else [],
        'source': 'workflow_config_parse',
    }
    created_at = _now_iso()
    record = {
        'id': str(uuid.uuid4()),
        'type': 'ztf-workflow-uat',
        'source': 'ztf-workflow',
        'status': _evidence_summary_status(readiness, None, schema_validation),
        'createdAt': created_at,
        'createdBy': user or 'unknown',
        'notes': str(data.get('notes') or '').strip(),
        'workflow': workflow,
        'executionStatus': execution_status,
        'returnCode': return_code,
        'configFile': config_file,
        'configSha256': _sha256_text(config_content),
        'approvalId': approval_id,
        'jobId': job_id,
        'taskIds': task_ids,
        'readiness': readiness,
        'schemaValidation': schema_validation,
        'compatibility': None,
        'generatedYaml': config_content,
        'outputExcerpt': output_excerpt,
        'metadata': data.get('metadata') if isinstance(data.get('metadata'), dict) else {},
    }
    if isinstance(parsed, dict):
        record['configTopLevelKeys'] = sorted(str(key) for key in parsed.keys())[:50]
    return record


def _build_nkp_validation_evidence(data: dict, user: str) -> dict:
    profile_id = str(data.get('profileId') or '').strip()
    profile = None
    if profile_id:
        profile = next((item for item in _list_nkp_profiles() if item.get('id') == profile_id), None)
        if not profile:
            raise ValueError('NKP deployment profile was not found')
    elif isinstance(data.get('profile'), dict):
        profile = _normalize_nkp_profile(data['profile'])

    generated_yaml = ''
    readiness: dict = {}
    schema_validation: dict = {}
    compatibility = None

    if profile:
        generated_yaml = _nkp_profile_to_yaml(profile)
        readiness = _nkp_profile_readiness(profile)
        schema_validation = _nkp_schema_validate_content(generated_yaml)
        if data.get('includeCompatibility'):
            binary_path = str(((profile.get('nkp') or {}).get('binaryPath')) or '').strip()
            if binary_path:
                compatibility = _nkp_cli_compatibility(binary_path)

    if not generated_yaml and data.get('configFile'):
        path = safe_config_path(str(data.get('configFile') or ''), get_configs_dir())
        if path and path.exists():
            generated_yaml = path.read_text(encoding='utf-8')
            schema_validation = schema_validation or _nkp_schema_validate_content(generated_yaml)

    if not generated_yaml:
        raise ValueError('generatedYaml, configFile, profileId, or profile is required')

    if not readiness:
        readiness = {'status': 'unknown', 'score': 0, 'summary': {'passed': 0, 'warnings': 0, 'failed': 0}, 'checks': []}
    schema_validation = _nkp_schema_validate_content(generated_yaml)

    job_id = str(data.get('jobId') or '').strip()
    job = _job_manager.get_job(job_id) if job_id else None
    output_excerpt = _redact_command_output(data.get('output') or '')
    if job and not output_excerpt:
        output_excerpt = _redact_command_output('\n'.join(
            str(event.get('data') or '') for event in job.get('logs', [])[-80:]
        ))

    created_at = _now_iso()
    return {
        'id': str(uuid.uuid4()),
        'type': str(data.get('type') or 'nkp-validation'),
        'source': 'nkp',
        'status': _evidence_summary_status(readiness, compatibility, schema_validation),
        'createdAt': created_at,
        'createdBy': user or 'unknown',
        'notes': str(data.get('notes') or '').strip(),
        'profileId': (profile or {}).get('id') or profile_id,
        'profileName': (profile or {}).get('name') or str(data.get('profileName') or '').strip(),
        'profileRevision': _profile_revision_value(profile) if profile else data.get('profileRevision'),
        'configFile': str(data.get('configFile') or '').strip(),
        'approvalId': str(data.get('approvalId') or '').strip(),
        'jobId': job_id,
        'taskIds': job.get('taskIds', []) if job else data.get('taskIds', []),
        'readiness': readiness,
        'schemaValidation': schema_validation,
        'compatibility': compatibility,
        'generatedYaml': generated_yaml,
        'outputExcerpt': output_excerpt,
        'metadata': data.get('metadata') if isinstance(data.get('metadata'), dict) else {},
    }


def _build_native_foundation_validation_evidence(data: dict, user: str) -> dict:
    config_content = str(data.get('configContent') or data.get('content') or '')
    config_file = str(data.get('configFile') or '').strip()
    if not config_content and config_file:
        path = safe_config_path(config_file, get_configs_dir())
        if path and path.exists():
            config_content = path.read_text(encoding='utf-8')
    if not config_content.strip():
        raise ValueError('native Foundation evidence requires configContent or configFile')

    try:
        parsed = yaml.safe_load(config_content) or {}
    except yaml.YAMLError as exc:
        raise ValueError(f'YAML parse error: {exc}') from exc
    if not isinstance(parsed, dict):
        raise ValueError('Native Foundation intent must be a YAML mapping')

    phase = str(data.get('phase') or data.get('deploymentPhase') or 'full_deployment').strip() or 'full_deployment'
    approval_id = str(data.get('approvalId') or data.get('approval_id') or '').strip()
    packet = _native_foundation_review_packet_manifest(
        parsed,
        config_content,
        phase,
        approval_id=approval_id,
    )
    if packet['status'] == 'invalid':
        raise ValueError('Native Foundation evidence requires valid planning intent')
    packet_payloads = packet.get('artifactPayloads') if isinstance(packet.get('artifactPayloads'), dict) else {}
    redacted_intent = str(packet_payloads.get('intent-redacted.yml') or '')
    readiness = {
        'status': 'blocked',
        'score': 0,
        'summary': {
            'passed': 0,
            'warnings': 0,
            'failed': 1,
        },
        'checks': [
            {
                'id': 'native_foundation_read_only',
                'label': 'Native Foundation execution remains read-only',
                'status': 'fail',
                'detail': 'Review packet evidence does not authorize imaging, hardware mutation, or cluster creation.',
            },
            {
                'id': 'review_packet_exported',
                'label': 'Review packet manifest generated',
                'status': 'pass',
                'detail': packet['packetId'],
            },
        ],
    }
    schema_validation = {
        'status': 'pass',
        'missing': [],
        'warnings': ['Native Foundation evidence is planning-only; mutating adapters remain disabled.'],
        'source': 'native_foundation_review_packet',
    }
    manifest = {
        key: value
        for key, value in packet.items()
        if key != 'artifactPayloads'
    }
    packet_gate_summary = manifest.get('nativeFoundationGateSummary') if isinstance(manifest.get('nativeFoundationGateSummary'), dict) else {}
    manifest_summary = manifest.get('summary') if isinstance(manifest.get('summary'), dict) else {}
    record = {
        'id': str(uuid.uuid4()),
        'type': 'native-foundation-review-packet',
        'source': 'native-foundation',
        'status': 'blocked',
        'createdAt': _now_iso(),
        'createdBy': user or 'unknown',
        'notes': str(data.get('notes') or '').strip(),
        'workflow': NATIVE_FOUNDATION_WORKFLOW,
        'executionStatus': 'planning_only',
        'returnCode': None,
        'configFile': config_file,
        'configSha256': _sha256_text(config_content),
        'approvalId': approval_id,
        'jobId': '',
        'taskIds': [],
        'readiness': readiness,
        'schemaValidation': schema_validation,
        'compatibility': None,
        'generatedYaml': redacted_intent,
        'outputExcerpt': '',
        'metadata': {
            **(data.get('metadata') if isinstance(data.get('metadata'), dict) else {}),
            'nativeFoundationPacketId': packet['packetId'],
            'nativeFoundationPlanId': packet['planId'],
            'nativeFoundationContractVersion': packet['contractVersion'],
            'nativeFoundationPhase': phase,
            'nativeFoundationApprovalId': approval_id or None,
            'nativeFoundationExecutionAuthorizationCarriedPersistenceGateStatus': packet_gate_summary.get('executionAuthorizationCarriedPersistenceGateStatus'),
            'nativeFoundationExecutionAuthorizationCarriedPersistenceGateEvidence': packet_gate_summary.get('executionAuthorizationCarriedPersistenceGateEvidence'),
            'nativeFoundationExecutionAuthorizationCarriedPersistenceRecordCount': packet_gate_summary.get('executionAuthorizationCarriedPersistenceRecordCount', 0),
            'nativeFoundationExecutionAuthorizationMissingCarriedPersistenceRecordCount': packet_gate_summary.get('executionAuthorizationMissingCarriedPersistenceRecordCount', 0),
            'nativeFoundationExecutionAuthorizationPersistenceControlledUatCompletionGateSummaryCount': packet_gate_summary.get('executionAuthorizationPersistenceControlledUatCompletionGateSummaryCount', 0),
            'nativeFoundationExecutionAuthorizationPersistenceControlledUatCompletionRequiredCount': packet_gate_summary.get('executionAuthorizationPersistenceControlledUatCompletionRequiredCount', 0),
            'nativeFoundationControlledUatCompletionStatus': packet_gate_summary.get('controlledUatCompletionStatus'),
            'nativeFoundationControlledUatCompletionRecordCount': packet_gate_summary.get('controlledUatCompletionRecordCount', 0),
            'nativeFoundationCompletedUatCount': packet_gate_summary.get('completedUatCount', 0),
            'nativeFoundationCanMarkUatComplete': packet_gate_summary.get('canMarkUatComplete'),
            'nativeFoundationControlledUatCompletionRequiredCount': packet_gate_summary.get('controlledUatCompletionRequiredCount', 0),
            'nativeFoundationControlledUatCompletionSourceStatus': packet_gate_summary.get('controlledUatCompletionSourceStatus'),
            'nativeFoundationProviderTopologyMatrixStatus': packet_gate_summary.get('providerTopologyMatrixStatus'),
            'nativeFoundationProviderTopologyMatrixRowCount': packet_gate_summary.get('providerTopologyMatrixRowCount', manifest_summary.get('providerTopologyMatrixRowCount', 0)),
            'nativeFoundationProviderTopologyMissingEvidenceCount': packet_gate_summary.get('providerTopologyMissingEvidenceCount', manifest_summary.get('providerTopologyMissingEvidenceCount', 0)),
            'nativeFoundationProviderTopologyMutatingEnabledRowCount': packet_gate_summary.get('providerTopologyMutatingEnabledRowCount', manifest_summary.get('providerTopologyMutatingEnabledRowCount', 0)),
            'nativeFoundationProviderOperationCatalogStatus': packet_gate_summary.get('providerOperationCatalogStatus'),
            'nativeFoundationProviderOperationCatalogRowCount': packet_gate_summary.get('providerOperationCatalogRowCount', manifest_summary.get('providerOperationCatalogRowCount', 0)),
            'nativeFoundationProviderOperationCatalogOperationCount': packet_gate_summary.get('providerOperationCatalogOperationCount', manifest_summary.get('providerOperationCatalogOperationCount', 0)),
            'nativeFoundationProviderOperationCatalogMutatingOperationCount': packet_gate_summary.get('providerOperationCatalogMutatingOperationCount', manifest_summary.get('providerOperationCatalogMutatingOperationCount', 0)),
            'nativeFoundationProviderOperationCatalogRunnableOperationCount': packet_gate_summary.get('providerOperationCatalogRunnableOperationCount', manifest_summary.get('providerOperationCatalogRunnableOperationCount', 0)),
            'nativeFoundationProviderOperationAdmissionStatus': packet_gate_summary.get('providerOperationAdmissionStatus'),
            'nativeFoundationProviderOperationAdmissionRecordCount': packet_gate_summary.get('providerOperationAdmissionRecordCount', manifest_summary.get('providerOperationAdmissionRecordCount', 0)),
            'nativeFoundationProviderOperationAdmittedCount': packet_gate_summary.get('providerOperationAdmittedCount', manifest_summary.get('providerOperationAdmittedCount', 0)),
            'nativeFoundationProviderOperationRunnableCount': packet_gate_summary.get('providerOperationRunnableCount', manifest_summary.get('providerOperationRunnableCount', 0)),
            'nativeFoundationProviderOperationQueuePlanStatus': packet_gate_summary.get('providerOperationQueuePlanStatus'),
            'nativeFoundationProviderOperationQueueItemCount': packet_gate_summary.get('providerOperationQueueItemCount', manifest_summary.get('providerOperationQueueItemCount', 0)),
            'nativeFoundationProviderOperationQueuedCount': packet_gate_summary.get('providerOperationQueuedCount', manifest_summary.get('providerOperationQueuedCount', 0)),
            'nativeFoundationProviderOperationQueuePersistedCount': packet_gate_summary.get('providerOperationQueuePersistedCount', manifest_summary.get('providerOperationQueuePersistedCount', 0)),
            'nativeFoundationProviderOperationQueueAdmissionStatus': packet_gate_summary.get('providerOperationQueueAdmissionStatus'),
            'nativeFoundationProviderOperationQueueAdmissionRecordCount': packet_gate_summary.get('providerOperationQueueAdmissionRecordCount', manifest_summary.get('providerOperationQueueAdmissionRecordCount', 0)),
            'nativeFoundationProviderOperationQueueAdmittedCount': packet_gate_summary.get('providerOperationQueueAdmittedCount', manifest_summary.get('providerOperationQueueAdmittedCount', 0)),
        },
        'nativeFoundationReviewPacket': manifest,
        'nativeFoundationArtifactHashes': packet.get('artifactHashes') or {},
    }
    if isinstance(parsed, dict):
        record['configTopLevelKeys'] = sorted(str(key) for key in parsed.keys())[:50]
    return record


def _build_validation_evidence(data: dict, user: str) -> dict:
    source = str(data.get('source') or data.get('type') or '').strip().lower()
    if source in {'native-foundation', 'native-foundation-review', 'native-foundation-review-packet'}:
        record = _build_native_foundation_validation_evidence(data, user)
    elif source in {'ztf-workflow', 'ztf-workflow-uat', 'workflow', 'generic-uat'} or data.get('workflow'):
        record = _build_workflow_validation_evidence(data, user)
    else:
        record = _build_nkp_validation_evidence(data, user)

    evidence = _list_validation_evidence()
    evidence.insert(0, record)
    _save_validation_evidence(evidence)
    log.info('validation_evidence_created', extra={
        'event': 'validation_evidence_created',
        'action': 'create_validation_evidence',
        'user': user,
        'evidenceId': record['id'],
        'status': record['status'],
        'profileId': record.get('profileId'),
        'workflow': record.get('workflow'),
        'source': record.get('source'),
    })
    return record


def _validation_evidence_markdown(record: dict) -> str:
    title = record.get('profileName') or record.get('workflow') or record.get('id')
    lines = [
        f"# Validation Evidence - {title}",
        '',
        f"- Source: {record.get('source') or record.get('type') or 'n/a'}",
        f"- Status: {record.get('status')}",
        f"- Created: {record.get('createdAt')}",
        f"- Created by: {record.get('createdBy')}",
        f"- Workflow: {record.get('workflow') or 'n/a'}",
        f"- Execution status: {record.get('executionStatus') or 'n/a'}",
        f"- Return code: {record.get('returnCode') if record.get('returnCode') is not None else 'n/a'}",
        f"- Profile: {record.get('profileName') or 'n/a'}",
        f"- Profile revision: {record.get('profileRevision') or 'n/a'}",
        f"- Config file: {record.get('configFile') or 'n/a'}",
        f"- Config SHA-256: {record.get('configSha256') or 'n/a'}",
        f"- Approval ID: {record.get('approvalId') or 'n/a'}",
        f"- Job ID: {record.get('jobId') or 'n/a'}",
        f"- Task IDs: {', '.join(record.get('taskIds') or []) or 'n/a'}",
        '',
        '## Readiness',
        '',
        f"- Status: {(record.get('readiness') or {}).get('status', 'unknown')}",
        f"- Score: {(record.get('readiness') or {}).get('score', 0)}%",
        '',
    ]
    for check in (record.get('readiness') or {}).get('checks', []):
        lines.append(f"- {check.get('status', '').upper()}: {check.get('label')} - {check.get('detail')}")
    lines += ['', '## Schema Validation', '', f"- Status: {(record.get('schemaValidation') or {}).get('status', 'unknown')}"]
    missing = (record.get('schemaValidation') or {}).get('missing') or []
    warnings = (record.get('schemaValidation') or {}).get('warnings') or []
    if missing:
        lines.append(f"- Missing: {', '.join(missing)}")
    if warnings:
        lines.append(f"- Warnings: {'; '.join(warnings)}")
    if record.get('configTopLevelKeys'):
        lines += ['', '## Config Inventory', '', f"- Top-level keys: {', '.join(record.get('configTopLevelKeys') or [])}"]
    native_packet = record.get('nativeFoundationReviewPacket') or {}
    if native_packet:
        lines += [
            '',
            '## Native Foundation Review Packet',
            '',
            f"- Packet ID: {native_packet.get('packetId') or 'n/a'}",
            f"- Plan ID: {native_packet.get('planId') or 'n/a'}",
            f"- Contract version: {native_packet.get('contractVersion') or 'n/a'}",
            f"- Evidence packs: {(native_packet.get('summary') or {}).get('evidencePackCount', 'n/a')}",
            f"- UAT cases: {(native_packet.get('summary') or {}).get('uatCaseCount', 'n/a')}",
            f"- Provider/topology matrix status: {(native_packet.get('nativeFoundationGateSummary') or {}).get('providerTopologyMatrixStatus', 'n/a')}",
            f"- Provider/topology matrix rows: {(native_packet.get('nativeFoundationGateSummary') or {}).get('providerTopologyMatrixRowCount', 'n/a')}",
            f"- Provider/topology missing evidence: {(native_packet.get('nativeFoundationGateSummary') or {}).get('providerTopologyMissingEvidenceCount', 'n/a')}",
            f"- Provider/topology mutating rows enabled: {(native_packet.get('nativeFoundationGateSummary') or {}).get('providerTopologyMutatingEnabledRowCount', 'n/a')}",
            f"- Provider operation catalog status: {(native_packet.get('nativeFoundationGateSummary') or {}).get('providerOperationCatalogStatus', 'n/a')}",
            f"- Provider operation catalog rows: {(native_packet.get('nativeFoundationGateSummary') or {}).get('providerOperationCatalogRowCount', 'n/a')}",
            f"- Provider operation catalog operations: {(native_packet.get('nativeFoundationGateSummary') or {}).get('providerOperationCatalogOperationCount', 'n/a')}",
            f"- Provider operation catalog runnable operations: {(native_packet.get('nativeFoundationGateSummary') or {}).get('providerOperationCatalogRunnableOperationCount', 'n/a')}",
            f"- Provider operation admission status: {(native_packet.get('nativeFoundationGateSummary') or {}).get('providerOperationAdmissionStatus', 'n/a')}",
            f"- Provider operation admission records: {(native_packet.get('nativeFoundationGateSummary') or {}).get('providerOperationAdmissionRecordCount', 'n/a')}",
            f"- Provider operations admitted: {(native_packet.get('nativeFoundationGateSummary') or {}).get('providerOperationAdmittedCount', 'n/a')}",
            f"- Provider operations runnable: {(native_packet.get('nativeFoundationGateSummary') or {}).get('providerOperationRunnableCount', 'n/a')}",
            f"- Provider operation queue plan status: {(native_packet.get('nativeFoundationGateSummary') or {}).get('providerOperationQueuePlanStatus', 'n/a')}",
            f"- Provider operation queue items: {(native_packet.get('nativeFoundationGateSummary') or {}).get('providerOperationQueueItemCount', 'n/a')}",
            f"- Provider operations queued: {(native_packet.get('nativeFoundationGateSummary') or {}).get('providerOperationQueuedCount', 'n/a')}",
            f"- Provider operation queues persisted: {(native_packet.get('nativeFoundationGateSummary') or {}).get('providerOperationQueuePersistedCount', 'n/a')}",
            f"- Provider operation queue admission status: {(native_packet.get('nativeFoundationGateSummary') or {}).get('providerOperationQueueAdmissionStatus', 'n/a')}",
            f"- Provider operation queue admission records: {(native_packet.get('nativeFoundationGateSummary') or {}).get('providerOperationQueueAdmissionRecordCount', 'n/a')}",
            f"- Provider operation queues admitted: {(native_packet.get('nativeFoundationGateSummary') or {}).get('providerOperationQueueAdmittedCount', 'n/a')}",
            f"- Controlled UAT completion status: {(native_packet.get('nativeFoundationGateSummary') or {}).get('controlledUatCompletionStatus', 'n/a')}",
            f"- Controlled UAT completion records: {(native_packet.get('nativeFoundationGateSummary') or {}).get('controlledUatCompletionRecordCount', 'n/a')}",
            f"- Auth persistence completion gate summaries: {(native_packet.get('nativeFoundationGateSummary') or {}).get('executionAuthorizationPersistenceControlledUatCompletionGateSummaryCount', 'n/a')}",
            f"- Can mark UAT complete: {(native_packet.get('nativeFoundationGateSummary') or {}).get('canMarkUatComplete', 'n/a')}",
        ]
    compatibility = record.get('compatibility') or {}
    if compatibility:
        lines += ['', '## NKP CLI Compatibility', '', f"- Status: {compatibility.get('status', 'unknown')}"]
        for check in compatibility.get('checks', []):
            lines.append(f"- {check.get('status', '').upper()}: {check.get('label')} - {check.get('detail')}")
    lines += ['', '## Notes', '', record.get('notes') or 'No notes supplied.', '']
    return '\n'.join(lines)


def _validation_evidence_zip(record: dict) -> BytesIO:
    buffer = BytesIO()
    safe_id = _safe_nkp_binary_filename(record.get('id') or 'validation-evidence')
    with zipfile.ZipFile(buffer, 'w', compression=zipfile.ZIP_DEFLATED) as zf:
        zf.writestr(f'{safe_id}/evidence.json', json.dumps(record, indent=2))
        zf.writestr(f'{safe_id}/summary.md', _validation_evidence_markdown(record))
        if record.get('generatedYaml'):
            zf.writestr(f'{safe_id}/generated.yaml', record.get('generatedYaml'))
        if record.get('outputExcerpt'):
            zf.writestr(f'{safe_id}/output.txt', record.get('outputExcerpt'))
        if record.get('nativeFoundationReviewPacket'):
            zf.writestr(
                f'{safe_id}/native-foundation-review-packet-manifest.json',
                json.dumps(record.get('nativeFoundationReviewPacket'), indent=2, sort_keys=True),
            )
        if record.get('nativeFoundationArtifactHashes'):
            zf.writestr(
                f'{safe_id}/native-foundation-artifact-hashes.json',
                json.dumps(record.get('nativeFoundationArtifactHashes'), indent=2, sort_keys=True),
            )
    buffer.seek(0)
    return buffer


def _set_default_nkp_binary(binaries: list[dict], binary_id: str) -> bool:
    found = False
    for item in binaries:
        is_target = item.get('id') == binary_id
        item['default'] = is_target
        if is_target:
            item['updatedAt'] = _now_iso()
            found = True
    return found


def _slugify(value: str, fallback: str = 'nkp-profile') -> str:
    slug = re.sub(r'[^a-z0-9-]+', '-', (value or '').strip().lower()).strip('-')
    return slug or fallback


def _split_csv(value) -> list[str]:
    if isinstance(value, list):
        return [str(item).strip() for item in value if str(item).strip()]
    return [item.strip() for item in str(value or '').split(',') if item.strip()]


