def _is_allowed_approval_workflow(workflow: str) -> bool:
    if workflow in ALLOWED_WORKFLOWS:
        return True
    if workflow.startswith('nkp:'):
        return workflow.split(':', 1)[1] in NKP_SAFE_PHASES
    if workflow in {'ztf2:apply', 'ztf2:destroy'}:
        return True
    return False

