TASK_ID_RE = re.compile(
    r'\b(?:task(?:_id| id)?|task_uuid|task uuid|nutanix task)\s*[:=]?\s*'
    r'([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12})\b'
)


def _nkp_approval_error(
    approval: dict | None,
    phase: str,
    config_file: str,
    config_content: str,
) -> str | None:
    if not approval:
        return 'Approved NKP execution request was not found'
    if approval.get('status') != 'approved':
        return 'NKP execution request is not approved'
    if approval.get('workflow') != f'nkp:{phase}':
        return 'NKP execution approval does not match the requested phase'
    expires = _parse_iso_datetime(approval.get('expiresAt'))
    if expires and expires < datetime.datetime.now(datetime.timezone.utc):
        return 'NKP execution approval has expired'
    approved_config_file = str(approval.get('configFile') or '').strip()
    if approved_config_file and config_file and approved_config_file != config_file:
        return 'NKP execution approval does not match the requested config file'
    approved_content = approval.get('configContent') or ''
    if approved_content and config_content and approved_content != config_content:
        return 'NKP execution approval does not match the requested YAML content'
    return None

# ─── Dry-run preflight definitions ───────────────────────────────────────────
# required: top-level YAML keys that must be present and non-empty
# ip_fields: keys whose values must be valid IP addresses
# connect: [(field_key, port, label)] — TCP reachability checks
# cluster_dict_connect: (port, label) — check each key of a clusters:{ip: ...} map
# cluster_dict_required_keys: nested keys that each clusters:{ip: ...} value must include
def _approval_required_workflows(settings: dict | None = None) -> set[str]:
    configured = (settings or get_settings()).get('approvalRequiredWorkflows', None)
    if configured is None or not isinstance(configured, list):
        return set(DEFAULT_APPROVAL_REQUIRED_WORKFLOWS)
    return {str(item).strip() for item in configured if str(item).strip() in ALLOWED_WORKFLOWS}


def _workflow_requires_approval(workflow: str | None, settings: dict | None = None) -> bool:
    return bool(workflow and workflow in _approval_required_workflows(settings))


def _workflow_approval_error(
    approval: dict | None,
    workflow: str,
    config_file: str,
    config_content: str,
) -> str | None:
    if not approval:
        return 'Approved workflow execution request was not found'
    if approval.get('status') != 'approved':
        return 'Workflow execution request is not approved'
    if approval.get('workflow') != workflow:
        return 'Workflow execution approval does not match the requested workflow'
    expires = _parse_iso_datetime(approval.get('expiresAt'))
    if expires and expires < datetime.datetime.now(datetime.timezone.utc):
        return 'Workflow execution approval has expired'
    approved_config_file = str(approval.get('configFile') or '').strip()
    if approved_config_file and config_file and approved_config_file != config_file:
        return 'Workflow execution approval does not match the requested config file'
    approved_content = approval.get('configContent') or ''
    if approved_content and config_content and approved_content != config_content:
        return 'Workflow execution approval does not match the requested YAML content'
    return None


def _validate_workflow_approval(data: dict, settings: dict | None = None) -> tuple[str | None, dict | None]:
    workflow = str(data.get('workflow') or '').strip()
    if not _workflow_requires_approval(workflow, settings):
        return None, None
    _require_engines()
    approval_id = str(data.get('approvalId') or '').strip()
    if not approval_id:
        return f'Workflow "{workflow}" requires an approved approval request', None
    approval = _approval_manager.get_approval(approval_id)
    error = _workflow_approval_error(
        approval,
        workflow,
        str(data.get('configFile') or '').strip(),
        data.get('configContent') or '',
    )
    return error, approval


ZTF2_ACTIONS = {'plan', 'apply', 'refresh', 'destroy', 'examples'}
ZTF2_APPROVAL_ACTIONS = {'apply', 'destroy'}


def _ztf2_runtime_error(settings: dict) -> tuple[dict, int] | None:
    if not settings.get('ztf2Enabled'):
        return {'error': 'ZTF 2.x plan/apply mode is disabled in Admin Settings'}, 403
    info = _ztf2_detect(settings.get('ztf2Path') or ZTF2_DEFAULT, settings.get('ztf2Command') or ZTF2_COMMAND_DEFAULT)
    if not info.get('compatible'):
        return {'error': info['message'], 'ztf2': info}, 409
    return None


def _ztf2_project_dir(settings: dict) -> Path:
    root = Path(settings.get('ztf2ProjectDir') or (CONFIG_DIR / 'ztf2-projects' / 'default'))
    _secure_mkdir(root)
    _secure_mkdir(root / 'plans')
    return root


def _ztf2_plan_trace(data: dict, settings: dict, plan_id: str | None = None) -> dict:
    input_content = str(data.get('inputContent') or data.get('configContent') or '')
    global_content = str(data.get('globalContent') or '')
    state_file = Path(str(data.get('stateFile') or 'state.yml')).name or 'state.yml'
    return {
        'framework': 'ztf2',
        'runtimeMode': 'ztf2_iac',
        'action': str(data.get('ztf2Action') or data.get('action') or 'plan').strip().lower(),
        'inputFile': Path(str(data.get('inputFile') or data.get('configFile') or 'input.yml')).name,
        'globalFile': Path(str(data.get('globalFile') or 'global.yml')).name,
        'stateFile': state_file,
        'inputSha256': _sha256_text(input_content),
        'globalSha256': _sha256_text(global_content),
        'statePath': str(_ztf2_project_dir(settings) / state_file),
        'ztfVersionRef': ZTF2_REF,
        'workflowTemplate': str(data.get('workflowTemplate') or '').strip(),
        'planId': plan_id or '',
    }


def _ztf2_approval_error(approval: dict | None, plan_job: dict | None, trace: dict) -> str | None:
    if not approval:
        return 'ZTF 2.x apply/destroy requires an approved plan approval request'
    if approval.get('status') != 'approved':
        return 'ZTF 2.x plan approval is not approved'
    if approval.get('workflow') != f"ztf2:{trace.get('action')}":
        return 'ZTF 2.x approval does not match the requested action'
    expires = _parse_iso_datetime(approval.get('expiresAt'))
    if expires and datetime.datetime.now(datetime.timezone.utc) > expires:
        return 'ZTF 2.x plan approval has expired'
    if not plan_job or plan_job.get('status') != 'success':
        return 'ZTF 2.x apply/destroy requires a successful plan job'
    plan_trace = plan_job.get('trace') or {}
    approval_meta = approval.get('metadata') or {}
    for key in ('planId', 'inputSha256', 'globalSha256', 'statePath'):
        expected = str(plan_trace.get(key) or '')
        supplied = str(trace.get(key) or '')
        approved = str(approval_meta.get(key) or expected)
        if supplied != expected or approved != expected:
            return f'ZTF 2.x approval does not match the planned {key}'
    return None


def _approval_automation_error(workflow: str | None) -> str | None:
    if _workflow_requires_approval(workflow):
        return (
            f'Workflow "{workflow}" requires an approved approval request and must be '
            'submitted as a direct job with an approval ID'
        )
    return None


