def _env_flag(name: str) -> bool:
    return str(os.environ.get(name) or '').strip().lower() in {'1', 'true', 'yes', 'on'}


def _native_foundation_dell_idrac_live_discovery_enabled() -> bool:
    return _env_flag('ZTF_NATIVE_FOUNDATION_ENABLE_DELL_IDRAC_DISCOVERY')


def _native_foundation_dell_idrac_mutation_enabled() -> bool:
    return _env_flag('ZTF_NATIVE_FOUNDATION_ENABLE_DELL_IDRAC_MUTATION')


def _native_foundation_dell_idrac_uat_execution_gate(config: dict | None) -> tuple[bool, list[str]]:
    reasons: list[str] = []
    config = config if isinstance(config, dict) else {}
    requirements = _native_foundation_intent_contract_requirements(config)
    providers = requirements.get('providersInIntent') or []
    if requirements.get('status') == 'invalid':
        reasons.append('Native Foundation intent must validate before Dell iDRAC UAT deployment can start.')
    if not providers:
        reasons.append('At least one Dell iDRAC Redfish provider must be present in the native Foundation intent.')
    unsupported = [provider for provider in providers if provider != 'dell_idrac_redfish']
    if unsupported:
        reasons.append(f'Dell iDRAC UAT deployment is scoped to dell_idrac_redfish only; found {", ".join(unsupported)}.')
    if not _native_foundation_dell_idrac_live_discovery_enabled():
        reasons.append('Set ZTF_NATIVE_FOUNDATION_ENABLE_DELL_IDRAC_DISCOVERY=true before Dell iDRAC UAT deployment.')
    if not _native_foundation_dell_idrac_mutation_enabled():
        reasons.append('Set ZTF_NATIVE_FOUNDATION_ENABLE_DELL_IDRAC_MUTATION=true before Dell iDRAC UAT deployment.')
    return not reasons, reasons


def _native_foundation_dell_idrac_target(config: dict, bmc_address: str = '', credential_ref: str = '') -> tuple[str, str]:
    address = str(bmc_address or '').strip()
    credential = str(credential_ref or '').strip()
    for site in config.get('sites') or []:
        if not isinstance(site, dict):
            continue
        if str(site.get('hardware_provider') or '').strip() != 'dell_idrac_redfish':
            continue
        credential = credential or str(site.get('bmc_credential_ref') or '').strip()
        for cluster in site.get('clusters') or []:
            if not isinstance(cluster, dict):
                continue
            for node in cluster.get('nodes') or []:
                if not isinstance(node, dict):
                    continue
                address = address or str(node.get('bmc_address') or '').strip()
                credential = credential or str(node.get('bmc_credential_ref') or '').strip()
                if address:
                    return address, credential
    return address, credential


def _native_foundation_dell_idrac_redfish_probe(
    config: dict,
    content: str,
    bmc_address: str = '',
    credential_ref: str = '',
    verify_tls: bool = False,
) -> dict:
    plan = _native_foundation_plan(config, content)
    target_address, target_credential_ref = _native_foundation_dell_idrac_target(config, bmc_address, credential_ref)
    live_enabled = _native_foundation_dell_idrac_live_discovery_enabled()
    mutation_enabled = _native_foundation_dell_idrac_mutation_enabled()
    redfish_url = ''
    if target_address:
        redfish_url = target_address if '://' in target_address else f'https://{target_address}'
        parsed_url = urllib.parse.urlparse(redfish_url)
        redfish_url = urllib.parse.urlunparse((
            parsed_url.scheme or 'https',
            parsed_url.netloc or parsed_url.path,
            '/redfish/v1/',
            '',
            '',
            '',
        ))

    probe_status = 'not_attempted'
    service_root: dict = {}
    error = ''
    username = password = None
    if live_enabled and target_credential_ref:
        username, password, error = _lookup_credential_ref(target_credential_ref)
    elif live_enabled:
        error = 'bmc_credential_ref is required for live Dell iDRAC Redfish discovery.'

    if live_enabled and redfish_url and username and password and not error:
        credentials = base64.b64encode(f'{username}:{password}'.encode('utf-8')).decode('ascii')
        req = urllib.request.Request(
            redfish_url,
            headers={
                'Authorization': f'Basic {credentials}',
                'Accept': 'application/json',
                'User-Agent': 'ZTF-Orchestrator Native Foundation Dell iDRAC UAT',
            },
            method='GET',
        )
        context = ssl.create_default_context() if verify_tls else ssl._create_unverified_context()
        try:
            with urllib.request.urlopen(req, timeout=10, context=context) as resp:  # nosec B310 - operator-configured iDRAC endpoint gated by env flag.
                raw_body = resp.read(128 * 1024)
                service_root = json.loads(raw_body.decode('utf-8') or '{}')
                probe_status = 'pass' if 200 <= int(getattr(resp, 'status', 200)) < 300 else 'blocked'
        except (urllib.error.URLError, OSError, ValueError, json.JSONDecodeError) as exc:
            probe_status = 'fail'
            error = str(exc)
    elif live_enabled and not redfish_url:
        probe_status = 'fail'
        error = 'bmc_address is required for live Dell iDRAC Redfish discovery.'

    checks = [
        {
            'id': 'intent-valid',
            'label': 'Native Foundation intent validates',
            'status': 'pass' if plan.get('status') == 'valid' else 'fail',
            'evidence': plan.get('planId') if plan.get('status') == 'valid' else '; '.join(plan.get('warnings') or ['Intent validation failed']),
        },
        {
            'id': 'dell-idrac-provider-selected',
            'label': 'Dell iDRAC Redfish provider is selected',
            'status': 'pass' if 'dell_idrac_redfish' in {
                str(site.get('hardware_provider') or '').strip()
                for site in config.get('sites') or []
                if isinstance(site, dict)
            } else 'blocked',
            'evidence': 'dell_idrac_redfish' if target_address else 'Set sites[].hardware_provider to dell_idrac_redfish.',
        },
        {
            'id': 'redfish-target-declared',
            'label': 'Redfish target BMC address is declared',
            'status': 'pass' if target_address else 'blocked',
            'evidence': target_address or 'Declare nodes[].bmc_address or pass bmcAddress.',
        },
        {
            'id': 'credential-reference-declared',
            'label': 'BMC credential reference is declared',
            'status': 'pass' if target_credential_ref else 'blocked',
            'evidence': target_credential_ref or 'Declare sites[].bmc_credential_ref or pass credentialRef.',
        },
        {
            'id': 'live-discovery-env-enabled',
            'label': 'Live Dell iDRAC discovery is explicitly enabled',
            'status': 'pass' if live_enabled else 'blocked',
            'evidence': 'ZTF_NATIVE_FOUNDATION_ENABLE_DELL_IDRAC_DISCOVERY=true' if live_enabled else 'Set ZTF_NATIVE_FOUNDATION_ENABLE_DELL_IDRAC_DISCOVERY=true for controlled UAT discovery.',
        },
        {
            'id': 'redfish-service-root-reachable',
            'label': 'Redfish service root is reachable',
            'status': probe_status if probe_status in {'pass', 'fail'} else 'blocked',
            'evidence': redfish_url if probe_status == 'pass' else error or 'Live discovery did not run.',
        },
        {
            'id': 'dell-idrac-mutation-disabled',
            'label': 'Dell iDRAC probe is read-only',
            'status': 'pass',
            'evidence': 'ZTF_NATIVE_FOUNDATION_ENABLE_DELL_IDRAC_MUTATION is not enabled; probe remains read-only.' if not mutation_enabled else 'Mutation environment flag is enabled separately; this probe still performs read-only service-root discovery.',
        },
    ]
    return {
        'workflow': NATIVE_FOUNDATION_WORKFLOW,
        'contractVersion': NATIVE_FOUNDATION_ADAPTER_CONTRACT_VERSION,
        'adapterInterfaceVersion': 'native-foundation-provider-adapter/dell-idrac-redfish/v1.8.1-controlled-uat',
        'providerId': 'dell_idrac_redfish',
        'readOnly': True,
        'mutatingActionsEnabled': False,
        'liveDiscoveryEnabled': live_enabled,
        'mutationEnvironmentEnabled': mutation_enabled,
        'status': 'ready' if probe_status == 'pass' else 'failed' if probe_status == 'fail' else 'blocked',
        'canRunLiveDiscovery': live_enabled and bool(redfish_url and target_credential_ref),
        'canRunMutatingOperations': False,
        'planId': plan.get('planId'),
        'intentSha256': plan.get('intentSha256'),
        'discoverySha256': plan.get('discoverySha256'),
        'redfishTarget': {
            'bmcAddress': target_address or None,
            'serviceRootUrl': redfish_url or None,
            'credentialRef': target_credential_ref or None,
            'verifyTls': bool(verify_tls),
        },
        'serviceRoot': {
            key: service_root.get(key)
            for key in ('@odata.id', '@odata.type', 'Id', 'Name', 'RedfishVersion', 'UUID')
            if isinstance(service_root, dict) and key in service_root
        },
        'checks': checks,
        'summary': {
            **(plan.get('summary') or {}),
            'checkCount': len(checks),
            'passedCheckCount': sum(1 for check in checks if check['status'] == 'pass'),
            'blockedCheckCount': sum(1 for check in checks if check['status'] == 'blocked'),
            'failedCheckCount': sum(1 for check in checks if check['status'] == 'fail'),
            'liveProbeAttemptedCount': 1 if live_enabled and redfish_url and username and password and not error else 0,
            'mutatingOperationEnabledCount': 0,
        },
        'requiredActions': [
            check['evidence'] for check in checks
            if check['status'] in {'blocked', 'fail'} and check['id'] != 'dell-idrac-mutation-disabled'
        ] + ['Keep Dell iDRAC power, boot, virtual media, and imaging mutation disabled until controlled UAT evidence and execution authorization pass.'],
        'warnings': [
            'Dell iDRAC Redfish probe performs at most a gated GET against the service root; it does not power cycle, change boot order, mount media, image nodes, or create clusters.',
            'Credential values are not returned in the response.',
        ],
    }
STANDALONE_FCA_IMAGE_CHECKS = [
    (
        'aos_image_ext_id',
        'AOS image',
        'AOS images',
        "config/images?$page=0&$limit=100&$filter=type%20eq%20Lifecycle.Config.ImageType%27AOS%27&$orderby=name",
    ),
    (
        'hypervisor_image_ext_id',
        'Hypervisor image',
        'hypervisor images',
        "config/images?$page=0&$limit=100&$filter=type%20eq%20Lifecycle.Config.ImageType%27AHV%27&$orderby=name",
    ),
]


def _native_foundation_phase_catalog() -> dict:
    phases = [dict(phase) for phase in sorted(NATIVE_FOUNDATION_PHASES, key=lambda item: item['order'])]
    implemented = [phase for phase in phases if str(phase.get('status', '')).startswith('implemented')]
    mutating_enabled = [phase for phase in phases if phase.get('mutatingActionsEnabled')]
    return {
        'workflow': NATIVE_FOUNDATION_WORKFLOW,
        'contractVersion': NATIVE_FOUNDATION_ADAPTER_CONTRACT_VERSION,
        'readOnly': True,
        'mutatingActionsEnabled': False,
        'currentReleaseMarker': APP_VERSION,
        'currentExecutionMode': 'planning_only',
        'supportedReadinessPhases': sorted(NATIVE_FOUNDATION_SUPPORTED_READINESS_PHASES),
        'summary': {
            'phaseCount': len(phases),
            'implementedPhaseCount': len(implemented),
            'mutatingEnabledPhaseCount': len(mutating_enabled),
            'currentBoundary': 'Planning, review, UAT evidence, and adapter hardening only; deployment mutation remains disabled.',
        },
        'phases': phases,
        'requiredActions': [
            'Keep native Foundation execution read-only until an explicit future change enables one controlled, UAT-validated adapter scope.',
            'Update docs, support matrix, tests, and validation evidence whenever a phase status changes.',
        ],
    }


def _native_foundation_phase_advancement_review(config: dict, content: str, requested_phase_id: str) -> dict:
    catalog = _native_foundation_phase_catalog()
    phases = catalog['phases']
    phase_by_id = {phase['id']: phase for phase in phases}
    requested_phase = phase_by_id.get(requested_phase_id)
    if not requested_phase:
        return {
            'workflow': NATIVE_FOUNDATION_WORKFLOW,
            'contractVersion': NATIVE_FOUNDATION_ADAPTER_CONTRACT_VERSION,
            'readOnly': True,
            'mutatingActionsEnabled': False,
            'status': 'failed',
            'error': 'Native Foundation phase is not supported',
            'requestedPhaseId': requested_phase_id,
            'supportedPhaseIds': [phase['id'] for phase in phases],
        }

    plan = _native_foundation_plan(config, content)
    predecessor_phases = [phase for phase in phases if phase['order'] <= requested_phase['order']]
    predecessor_blockers = [
        phase for phase in predecessor_phases
        if not str(phase.get('status', '')).startswith('implemented')
    ]
    evidence_catalog = _native_foundation_evidence_catalog(config)
    phase_evidence_requirements = []
    for requirement in requested_phase.get('evidenceRequired') or []:
        status = _native_foundation_evidence_requirement_status(requirement, evidence_catalog)
        status['evidence'] = (
            status['evidenceId']
            if status['status'] == 'pass'
            else f"Accepted evidence ID required for foundation_engine.uat_evidence.{status['evidenceKey']}."
        )
        phase_evidence_requirements.append(status)
    missing_phase_evidence = [
        item for item in phase_evidence_requirements
        if item['status'] != 'pass'
    ]
    checks = [
        {
            'id': 'phase-known',
            'label': 'Requested phase is in the native Foundation catalog',
            'status': 'pass',
            'evidence': requested_phase['id'],
        },
        {
            'id': 'plan-valid',
            'label': 'Native Foundation intent validates for phase review',
            'status': 'pass' if plan['status'] == 'valid' else 'fail',
            'evidence': plan['planId'] if plan['status'] == 'valid' else '; '.join(plan.get('warnings') or ['Intent validation failed']),
        },
        {
            'id': 'prior-phases-implemented',
            'label': 'Prior phases are implemented as read-only foundation controls',
            'status': 'pass' if not predecessor_blockers else 'blocked',
            'evidence': (
                f'{len(predecessor_phases)} predecessor phase(s) implemented as read-only controls.'
                if not predecessor_blockers else
                ', '.join(phase['id'] for phase in predecessor_blockers)
            ),
        },
        {
            'id': 'phase-docs-bound',
            'label': 'Phase status is documented and release-test guarded',
            'status': 'pass',
            'evidence': 'docs/foundation-engine/phase-catalog.md and release-integrity phase catalog guard',
        },
        {
            'id': 'phase-evidence-accepted',
            'label': 'Requested phase evidence requirements are accepted',
            'status': 'pass' if phase_evidence_requirements and not missing_phase_evidence else 'blocked',
            'evidence': (
                'All requested phase evidence requirements have accepted evidence IDs.'
                if phase_evidence_requirements and not missing_phase_evidence else
                ', '.join(item['requirement'] for item in missing_phase_evidence) or 'No phase evidence requirements are declared.'
            ),
        },
        {
            'id': 'controlled-uat-completion-required',
            'label': 'Controlled UAT completion required before phase promotion',
            'status': 'blocked',
            'evidence': requested_phase.get('nextGate') or 'Controlled UAT evidence is required before promotion.',
        },
        {
            'id': 'mutating-enable-disabled',
            'label': 'Mutating phase enablement remains disabled',
            'status': 'blocked',
            'evidence': 'No phase can enable adapters, submit jobs, call Foundation, or mutate hardware in this release.',
        },
    ]
    failed = any(check['status'] == 'fail' for check in checks)
    blocked = any(check['status'] == 'blocked' for check in checks)
    return {
        'workflow': NATIVE_FOUNDATION_WORKFLOW,
        'contractVersion': NATIVE_FOUNDATION_ADAPTER_CONTRACT_VERSION,
        'readOnly': True,
        'mutatingActionsEnabled': False,
        'status': 'failed' if failed else 'blocked' if blocked else 'ready',
        'requestedPhase': requested_phase,
        'planId': plan['planId'],
        'intentSha256': plan['intentSha256'],
        'discoverySha256': plan['discoverySha256'],
        'checks': checks,
        'phaseEvidenceRequirements': phase_evidence_requirements,
        'summary': {
            'requestedPhaseOrder': requested_phase['order'],
            'predecessorPhaseCount': len(predecessor_phases),
            'blockedCheckCount': sum(1 for check in checks if check['status'] == 'blocked'),
            'failedCheckCount': sum(1 for check in checks if check['status'] == 'fail'),
            'mutatingEnabledPhaseCount': catalog['summary']['mutatingEnabledPhaseCount'],
            'requiredPhaseEvidenceCount': len(phase_evidence_requirements),
            'acceptedPhaseEvidenceCount': len(phase_evidence_requirements) - len(missing_phase_evidence),
            'missingPhaseEvidenceCount': len(missing_phase_evidence),
        },
        'requiredActions': [
            'Capture controlled UAT completion, adapter runtime admission, job persistence admission, backup/restore, and recovery evidence before promotion.',
            'Change phase status, documentation, release-integrity tests, and execution adapters in one future reviewed release before enabling mutation.',
        ],
        'message': 'Native Foundation phase advancement is review-only and remains blocked until controlled UAT proves the requested phase.',
    }


def _cluster_create_foundation_target(config: dict) -> str:
    """Return the Orchestrator-only Cluster Create Foundation Central target."""
    metadata = config.get('ztf_orchestrator')
    value = ''
    if isinstance(metadata, dict):
        value = str(metadata.get('foundation_central_target') or '').strip()
    if not value:
        value = str(config.get('foundation_central_target') or '').strip()
    if value in {FOUNDATION_TARGET_STANDALONE_FCA, 'foundation_central_appliance'}:
        return FOUNDATION_TARGET_STANDALONE_FCA
    return FOUNDATION_TARGET_INTEGRATED_PC_FC


def _standalone_fca_execution_error(workflow: str, config_content: str) -> str:
    if workflow != 'cluster-create' or not config_content:
        return ''
    try:
        parsed = yaml.safe_load(config_content) or {}
    except yaml.YAMLError:
        return ''
    if not isinstance(parsed, dict):
        return ''
    if _cluster_create_foundation_target(parsed) == FOUNDATION_TARGET_STANDALONE_FCA:
        return (
            'Standalone FCA configs must use workflow "cluster-create-standalone-fca" '
            'and config file "create_fca_cluster.yml".'
        )
    return ''


def _standalone_fca_confirmation(workflow: str) -> str:
    return f'{STANDALONE_FCA_CONFIRMATION_PREFIX} {workflow}'


def _validate_standalone_fca_ack(workflow: str | None, payload: dict) -> str | None:
    if workflow not in STANDALONE_FCA_WORKFLOWS:
        return None
    expected = _standalone_fca_confirmation(str(workflow))
    if str(payload.get('destructiveConfirmation') or '').strip() != expected:
        return (
            f'Standalone FCA execution acknowledgement required. Type exactly: {expected}'
        )
    return None


def _fca_api_version(config: dict) -> tuple[str, str]:
    api_version = str(config.get('fca_api_version') or STANDALONE_FCA_DEFAULT_API_VERSION).strip()
    if api_version not in {'v4.2.a2', 'v4.3'}:
        return api_version, 'Standalone FCA Lifecycle execution currently supports API v4.2.a2 or v4.3 only'
    return api_version, ''


def _json_collection_count(payload) -> int:
    if isinstance(payload, list):
        return len(payload)
    if not isinstance(payload, dict):
        return 0
    for key in ('data', 'entities', 'items'):
        value = payload.get(key)
        if isinstance(value, list):
            return len(value)
    return 1 if payload else 0


def _json_collection_items(payload) -> list:
    if isinstance(payload, list):
        return payload
    if not isinstance(payload, dict):
        return []
    for key in ('data', 'entities', 'items'):
        value = payload.get(key)
        if isinstance(value, list):
            return value
    return [payload] if payload else []


def _find_ext_id(payload, configured_ext_id: str, configured_name: str = '') -> tuple[bool, str]:
    items = _json_collection_items(payload)
    if configured_ext_id:
        for item in items:
            if isinstance(item, dict) and str(item.get('extId') or '') == configured_ext_id:
                return True, configured_ext_id
        return False, configured_ext_id
    if configured_name:
        for item in items:
            if isinstance(item, dict) and str(item.get('name') or '').lower() == configured_name.lower():
                return True, str(item.get('extId') or configured_name)
        return False, configured_name
    return True, ''


def _fca_single_image_ext_id(payload, label: str) -> tuple[str, str]:
    images = [
        item for item in _json_collection_items(payload)
        if isinstance(item, dict) and str(item.get('extId') or '').strip()
    ]
    if len(images) == 1:
        image = images[0]
        ext_id = str(image.get('extId') or '').strip()
        name = str(image.get('name') or ext_id).strip()
        return ext_id, f'{name} ({ext_id})'
    if not images:
        return '', f'{label} extId is required because no matching FCA image was found'
    return '', f'{label} extId is required because {len(images)} matching FCA images were found'


def _fca_hydrate_cluster_image_ext_ids(
    host: str,
    credential_ref: str,
    api_version: str,
    config: dict,
) -> tuple[bool, list[str], dict]:
    hydrated = dict(config)
    lines: list[str] = []
    for image_key, label, _payload_key, path in STANDALONE_FCA_IMAGE_CHECKS:
        if str(hydrated.get(image_key) or '').strip():
            continue
        ok, message, payload, latency_ms = _fca_lifecycle_get(host, credential_ref, api_version, path)
        if not ok:
            return False, [*lines, f'FCA {label} lookup failed: {message}'], hydrated
        image_ext_id, detail = _fca_single_image_ext_id(payload, label)
        if not image_ext_id:
            return False, [*lines, f'FCA {detail}'], hydrated
        hydrated[image_key] = image_ext_id
        lines.append(f'FCA {label} inferred from inventory: {detail} ({latency_ms:>5.0f}ms)')
    return True, lines, hydrated


def _fca_lifecycle_get(host: str, credential_ref: str, api_version: str, resource_path: str) -> tuple[bool, str, object, float]:
    return _fca_lifecycle_request(host, credential_ref, api_version, 'GET', resource_path)


def _fca_lifecycle_request(
    host: str,
    credential_ref: str,
    api_version: str,
    method: str,
    resource_path: str,
    payload: object | None = None,
) -> tuple[bool, str, object, float]:
    return _fca_api_request(host, credential_ref, f'lifecycle/{api_version}', method, resource_path, payload)


def _fca_prism_get(host: str, credential_ref: str, api_version: str, resource_path: str) -> tuple[bool, str, object, float]:
    return _fca_api_request(host, credential_ref, f'prism/{api_version}', 'GET', resource_path)


def _fca_api_request(
    host: str,
    credential_ref: str,
    api_root: str,
    method: str,
    resource_path: str,
    payload: object | None = None,
) -> tuple[bool, str, object, float]:
    username, password, error = _lookup_credential_ref(credential_ref)
    if error:
        return False, error, {}, 0.0
    token = base64.b64encode(f'{username}:{password}'.encode('utf-8')).decode('ascii')
    clean_path = resource_path.lstrip('/')
    clean_root = api_root.strip('/')
    url = f'https://{host}:9440/api/{clean_root}/{clean_path}'
    data = None
    headers = {
        'Authorization': f'Basic {token}',
        'Accept': 'application/json',
        'User-Agent': f'ZTF-Orchestrator/{APP_VERSION}',
    }
    if payload is not None:
        data = json.dumps(payload).encode('utf-8')
        headers['Content-Type'] = 'application/json'
    req = urllib.request.Request(url, headers={
        **headers,
    }, data=data, method=method.upper())
    context = ssl._create_unverified_context()
    started = time.monotonic()
    try:
        with urllib.request.urlopen(req, timeout=15, context=context) as resp:  # nosec B310 - operator-configured FCA endpoint.
            latency_ms = (time.monotonic() - started) * 1000
            raw = resp.read().decode('utf-8')
            payload = json.loads(raw) if raw.strip() else {}
            if 200 <= getattr(resp, 'status', 0) < 300:
                return True, f'HTTP {getattr(resp, "status", "unknown")}', payload, latency_ms
            return False, f'HTTP {getattr(resp, "status", "unknown")}', payload, latency_ms
    except urllib.error.HTTPError as exc:
        latency_ms = (time.monotonic() - started) * 1000
        return False, f'HTTP {exc.code}', {}, latency_ms
    except (urllib.error.URLError, OSError) as exc:
        return False, f'request failed: {getattr(exc, "reason", exc)}', {}, 0.0
    except json.JSONDecodeError:
        return False, 'response was not valid JSON', {}, 0.0


def _fca_execution_options(config: dict) -> dict:
    options = config.get('fca_execution')
    return options if isinstance(options, dict) else {}


def _fca_submit_path(workflow: str, config: dict) -> str:
    options = _fca_execution_options(config)
    value = str(options.get('submit_path') or config.get('fca_submit_path') or '').strip()
    return value or STANDALONE_FCA_DEFAULT_SUBMIT_PATHS.get(workflow, '')


def _fca_status_path_template(config: dict) -> str:
    options = _fca_execution_options(config)
    return str(options.get('status_path_template') or config.get('fca_status_path_template') or '').strip()


def _fca_status_poll_settings(config: dict) -> tuple[int, float]:
    options = _fca_execution_options(config)

    def _int_option(key: str, default: int) -> int:
        value = options.get(key, config.get(f'fca_{key}'))
        try:
            return int(value)
        except (TypeError, ValueError):
            return default

    def _float_option(key: str, default: float) -> float:
        value = options.get(key, config.get(f'fca_{key}'))
        try:
            return float(value)
        except (TypeError, ValueError):
            return default

    attempts = max(1, _int_option('status_poll_attempts', 30))
    interval_seconds = max(0.0, _float_option('status_poll_interval_seconds', 2.0))
    return attempts, interval_seconds


def _fca_default_status_path_template(workflow: str) -> str:
    return STANDALONE_FCA_DEFAULT_STATUS_PATHS.get(workflow, '')


def _fca_payload_override(config: dict) -> object | None:
    options = _fca_execution_options(config)
    if 'payload' in options:
        return options.get('payload')
    if 'fca_payload' in config:
        return config.get('fca_payload')
    return None


def _fca_node_intent(node: dict) -> dict:
    mapped = {
        'nodeSerial': node.get('node_serial'),
        'cvmIp': node.get('cvm_ip'),
        'hostIp': node.get('host_ip'),
        'ipmiIp': node.get('ipmi_ip'),
        'hypervisorHostname': node.get('hypervisor_hostname'),
        'cvmRamGb': node.get('cvm_ram_gb') or node.get('cvm_ram'),
        'cvmVlanId': node.get('cvm_vlan_id'),
    }
    return {key: value for key, value in mapped.items() if value not in (None, '', [])}


def _fca_ipv4(value: object, prefix_length: int | None = None) -> dict:
    ipv4 = {'value': str(value)}
    if prefix_length is not None:
        ipv4['prefixLength'] = prefix_length
    return {'ipv4': ipv4}


def _fca_ip_or_fqdn(value: object) -> dict:
    text = str(value)
    if re.match(r'^\d{1,3}(?:\.\d{1,3}){3}$', text):
        return _fca_ipv4(text)
    return {'fqdn': {'value': text}}


def _fca_network_list(values: object, *, ip_or_fqdn: bool = False) -> list[dict]:
    if not isinstance(values, list):
        return []
    result = []
    for value in values:
        if value in (None, ''):
            continue
        result.append(_fca_ip_or_fqdn(value) if ip_or_fqdn else _fca_ipv4(value))
    return result


def _prefix_length_from_netmask(value: object) -> int:
    text = str(value or '').strip()
    if not text:
        return 24
    if text.isdigit():
        number = int(text)
        return number if 0 <= number <= 32 else 24
    try:
        return ipaddress.ip_network(f'0.0.0.0/{text}').prefixlen
    except ValueError:
        return 24


def _fca_node_hostname(node: dict) -> str:
    return str(node.get('hypervisor_hostname') or node.get('hostname') or node.get('node_serial') or '').strip()


def _fca_build_cluster_workflow_payload(config: dict, resolved_nodes: dict[str, dict] | None = None) -> dict:
    common_network = config.get('common_network_settings') if isinstance(config.get('common_network_settings'), dict) else {}
    dns_servers = _fca_network_list(common_network.get('dns_servers'))
    ntp_servers = _fca_network_list(common_network.get('ntp_servers'), ip_or_fqdn=True)
    aos_image_ext_id = str(config.get('aos_image_ext_id') or '').strip()
    hypervisor_image_ext_id = str(config.get('hypervisor_image_ext_id') or '').strip()
    workflow_type = str(config.get('fca_workflow_type') or STANDALONE_FCA_CLUSTER_WORKFLOW_TYPE).strip()

    clusters = [cluster for cluster in config.get('create_clusters') or [] if isinstance(cluster, dict)]
    cluster = clusters[0] if clusters else {}
    host_prefix = _prefix_length_from_netmask(cluster.get('host_netmask') or cluster.get('cvm_netmask'))
    cvm_prefix = _prefix_length_from_netmask(cluster.get('cvm_netmask'))
    host_gateway = cluster.get('host_gateway') or cluster.get('cvm_gateway')
    cvm_gateway = cluster.get('cvm_gateway') or cluster.get('host_gateway')
    host_vlan = cluster.get('host_vlan_id') or cluster.get('cvm_vlan_id') or cluster.get('vlan_id')
    cvm_vlan = cluster.get('cvm_vlan_id') or cluster.get('host_vlan_id') or cluster.get('vlan_id')
    mtu = int(cluster.get('mtu') or 1500)

    payload_nodes = []
    for node in cluster.get('nodes_list') or []:
        if not isinstance(node, dict):
            continue
        serial = str(node.get('node_serial') or '').strip()
        hostname = _fca_node_hostname(node)
        resolved = (resolved_nodes or {}).get(serial) or {}
        node_ext_id = str(node.get('node_ext_id') or resolved.get('extId') or '').strip()
        host_ip = node.get('host_ip')
        cvm_ip = node.get('cvm_ip')
        cvm_ram = node.get('cvm_ram_gb') or node.get('cvm_ram') or cluster.get('cvm_ram_gb') or cluster.get('cvm_ram') or 48
        payload_nodes.append({
            'aosInstallationDetails': {
                'aosImageDetails': {'imageExtId': aos_image_ext_id},
                'managementNetwork': {
                    'gateway': _fca_ipv4(cvm_gateway),
                    'ip': _fca_ipv4(cvm_ip, cvm_prefix),
                    'vlanId': cvm_vlan,
                },
                'nameserverIPList': dns_servers,
                'ntpServerIPList': ntp_servers,
                'cvmMemoryGB': cvm_ram,
            },
            'hostInstallationDetails': {
                'imageDetails': {'imageExtId': hypervisor_image_ext_id},
                'type': str(config.get('hypervisor_type') or node.get('hypervisor_type') or 'AHV'),
                'networkDetails': {
                    'managementNetwork': {
                        'ip': _fca_ipv4(host_ip, host_prefix),
                        'gateway': _fca_ipv4(host_gateway),
                        'mtu': mtu,
                        'bondSettings': {},
                        'vlan': host_vlan,
                    },
                },
                'hostname': hostname,
                'nameserverIPList': dns_servers,
                'ntpServerIPList': ntp_servers,
            },
            'cvmIp': _fca_ipv4(cvm_ip, cvm_prefix),
            'nodeExtId': node_ext_id,
            'nodeRole': str(node.get('node_role') or 'COMPUTE'),
            'hostIp': _fca_ipv4(host_ip, host_prefix),
            'hostname': hostname,
            'uniqueIdentifierValue': serial,
        })

    return {
        'clusterDetails': {
            'externalIp': _fca_ipv4(cluster.get('cluster_vip')),
            'name': cluster.get('cluster_name'),
            'timezone': cluster.get('timezone') or 'UTC',
        },
        'name': cluster.get('cluster_name'),
        'nodes': payload_nodes,
        'workflowType': workflow_type,
    }


def _fca_has_ipv4_value(payload: object) -> bool:
    if not isinstance(payload, dict):
        return False
    ipv4 = payload.get('ipv4')
    if not isinstance(ipv4, dict):
        return False
    value = str(ipv4.get('value') or '').strip()
    return bool(value and value.lower() != 'none')


def _fca_validate_cluster_workflow_payload(payload: dict) -> list[str]:
    errors: list[str] = []
    cluster_details = payload.get('clusterDetails') if isinstance(payload.get('clusterDetails'), dict) else {}
    if not cluster_details.get('name'):
        errors.append('FCA workflow payload missing clusterDetails.name')
    if not _fca_has_ipv4_value(cluster_details.get('externalIp')):
        errors.append('FCA workflow payload missing clusterDetails.externalIp')
    if payload.get('workflowType') != STANDALONE_FCA_CLUSTER_WORKFLOW_TYPE:
        errors.append(f'FCA workflow payload workflowType must be {STANDALONE_FCA_CLUSTER_WORKFLOW_TYPE}')
    nodes = payload.get('nodes') if isinstance(payload.get('nodes'), list) else []
    if not nodes:
        errors.append('FCA workflow payload missing nodes')
    for index, node in enumerate(nodes, start=1):
        if not isinstance(node, dict):
            errors.append(f'FCA workflow payload nodes[{index}] is not an object')
            continue
        if not node.get('nodeExtId'):
            errors.append(f'FCA workflow payload nodes[{index}].nodeExtId was not resolved')
        if not node.get('uniqueIdentifierValue'):
            errors.append(f'FCA workflow payload nodes[{index}].uniqueIdentifierValue missing')
        aos = node.get('aosInstallationDetails') if isinstance(node.get('aosInstallationDetails'), dict) else {}
        host = node.get('hostInstallationDetails') if isinstance(node.get('hostInstallationDetails'), dict) else {}
        if not ((aos.get('aosImageDetails') or {}).get('imageExtId')):
            errors.append(f'FCA workflow payload nodes[{index}].aosInstallationDetails.aosImageDetails.imageExtId missing')
        if not ((host.get('imageDetails') or {}).get('imageExtId')):
            errors.append(f'FCA workflow payload nodes[{index}].hostInstallationDetails.imageDetails.imageExtId missing')
        aos_network = aos.get('managementNetwork') if isinstance(aos.get('managementNetwork'), dict) else {}
        host_network = ((host.get('networkDetails') or {}).get('managementNetwork') if isinstance(host.get('networkDetails'), dict) else {})
        if not _fca_has_ipv4_value(aos_network.get('ip')):
            errors.append(f'FCA workflow payload nodes[{index}].aosInstallationDetails.managementNetwork.ip missing')
        if not _fca_has_ipv4_value(host_network.get('ip')):
            errors.append(f'FCA workflow payload nodes[{index}].hostInstallationDetails.networkDetails.managementNetwork.ip missing')
        if not _fca_has_ipv4_value(aos_network.get('gateway')):
            errors.append(f'FCA workflow payload nodes[{index}].aosInstallationDetails.managementNetwork.gateway missing')
        if not _fca_has_ipv4_value(host_network.get('gateway')):
            errors.append(f'FCA workflow payload nodes[{index}].hostInstallationDetails.networkDetails.managementNetwork.gateway missing')
    return errors


def _build_standalone_fca_payload(workflow: str, config: dict) -> dict:
    override = _fca_payload_override(config)
    if override is not None:
        if isinstance(override, dict):
            return override
        return {'payload': override}

    base = {
        'metadata': {
            'source': 'ztf-orchestrator',
            'workflow': workflow,
            'foundationCentralTarget': FOUNDATION_TARGET_STANDALONE_FCA,
        },
        'hardwareProviderExtId': config.get('hardware_provider_ext_id') or None,
        'hardwareProviderName': config.get('hardware_provider_name') or None,
        'connectionExtId': config.get('connection_ext_id') or None,
        'aosImageExtId': config.get('aos_image_ext_id') or None,
        'hypervisorImageExtId': config.get('hypervisor_image_ext_id') or None,
        'commonNetworkSettings': config.get('common_network_settings') or {},
    }
    base = {key: value for key, value in base.items() if value not in (None, '', [])}

    if workflow == 'cluster-create-standalone-fca':
        return _fca_build_cluster_workflow_payload(config)

    if workflow in {'imaging-only-standalone-fca', 'imaging-standalone-fca'}:
        batches = []
        for batch in config.get('imaging_batches') or []:
            if not isinstance(batch, dict):
                continue
            nodes = [_fca_node_intent(node) for node in batch.get('nodes') or [] if isinstance(node, dict)]
            batches.append({'nodes': nodes})
        return {**base, 'imagingBatches': batches}

    if workflow == 'site-deploy-standalone-fca':
        sites = []
        for site in config.get('sites') or []:
            if not isinstance(site, dict):
                continue
            clusters = []
            for cluster in site.get('clusters') or []:
                if not isinstance(cluster, dict):
                    continue
                clusters.append({
                    'clusterName': cluster.get('cluster_name'),
                    'clusterVip': cluster.get('cluster_vip'),
                    'redundancyFactor': cluster.get('redundancy_factor'),
                    'clusterSize': cluster.get('cluster_size'),
                    'nodes': [_fca_node_intent(node) for node in cluster.get('node_details') or [] if isinstance(node, dict)],
                })
            sites.append({
                'siteName': site.get('site_name'),
                'useExistingNetworkSettings': site.get('use_existing_network_settings'),
                'reImage': site.get('re-image'),
                'network': site.get('network') or {},
                'clusters': clusters,
            })
        return {**base, 'sites': sites}

    return base


def _fca_config_nodes(config: dict) -> list[dict]:
    nodes: list[dict] = []
    for cluster in config.get('create_clusters') or []:
        if not isinstance(cluster, dict):
            continue
        nodes.extend([node for node in cluster.get('nodes_list') or [] if isinstance(node, dict)])
    return nodes


def _fca_node_serials(config: dict) -> list[str]:
    serials = []
    for node in _fca_config_nodes(config):
        serial = str(node.get('node_serial') or '').strip()
        if serial:
            serials.append(serial)
    return serials


def _fca_node_match_key(node: dict) -> str:
    return str(
        node.get('uniqueIdentifierValue')
        or node.get('blockSerialNumber')
        or node.get('serial')
        or node.get('node_serial')
        or ''
    ).strip()


def _fca_provider_connection_path(provider_ext_id: str, connection_ext_id: str, suffix: str = '') -> str:
    provider = urllib.parse.quote(provider_ext_id, safe='')
    connection = urllib.parse.quote(connection_ext_id, safe='')
    tail = suffix.lstrip('/')
    base = f'config/hardware-providers/{provider}/connections/{connection}'
    return f'{base}/{tail}' if tail else base


def _fca_resolve_onboarded_nodes(
    host: str,
    credential_ref: str,
    api_version: str,
    config: dict,
) -> tuple[bool, list[str], dict[str, dict]]:
    lines: list[str] = []
    serials = set(_fca_node_serials(config))
    resolved: dict[str, dict] = {}
    if not serials:
        return True, lines, resolved

    ok, message, payload, latency_ms = _fca_lifecycle_get(
        host,
        credential_ref,
        api_version,
        'config/nodes?$page=0&$limit=100&$filter=isOnboarded%20eq%20true&$orderby=createdTime%20asc',
    )
    if not ok:
        return False, [f'FCA onboarded node lookup failed: {message}'], resolved
    for item in _json_collection_items(payload):
        if not isinstance(item, dict):
            continue
        serial = _fca_node_match_key(item)
        if serial in serials:
            resolved[serial] = item
    lines.append(f'FCA onboarded node lookup: {len(resolved)}/{len(serials)} matched ({latency_ms:>5.0f}ms)')
    return True, lines, resolved


def _fca_poll_prism_task(host: str, credential_ref: str, task_ext_id: str) -> tuple[bool, list[str], dict]:
    lines: list[str] = []
    last_payload: dict = {}
    task_path = f'config/tasks/{urllib.parse.quote(task_ext_id, safe="")}?$select=*'
    terminal_success = {'succeeded', 'success', 'completed', 'complete'}
    terminal_failed = {'failed', 'failure', 'error', 'cancelled', 'canceled'}
    for attempt in range(1, 31):
        time.sleep(2)
        ok, message, payload, latency_ms = _fca_prism_get(
            host, credential_ref, STANDALONE_FCA_PRISM_TASK_API_VERSION, task_path,
        )
        last_payload = payload if isinstance(payload, dict) else {}
        if not ok:
            return False, [f'FCA Prism task poll failed: {message}'], last_payload
        data = payload.get('data') if isinstance(payload, dict) else {}
        status = str(data.get('status') if isinstance(data, dict) else '').strip()
        progress = data.get('progressPercentage') if isinstance(data, dict) else None
        display = status or 'unknown'
        suffix = f' {progress}%' if progress is not None else ''
        lines.append(f'FCA Prism task poll {attempt:02d}: {display}{suffix} ({latency_ms:>5.0f}ms)')
        normalized = display.lower()
        if normalized in terminal_success:
            return True, lines, last_payload
        if normalized in terminal_failed:
            return False, lines, last_payload
    return False, [*lines, 'FCA Prism task polling timed out after 60 seconds'], last_payload


def _fca_onboard_discovered_nodes(
    host: str,
    credential_ref: str,
    api_version: str,
    config: dict,
    resolved_nodes: dict[str, dict],
) -> tuple[bool, list[str], dict[str, dict], list[dict]]:
    lines: list[str] = []
    task_payloads: list[dict] = []
    provider_ext_id = str(config.get('hardware_provider_ext_id') or '').strip()
    connection_ext_id = str(config.get('connection_ext_id') or '').strip()
    serials = set(_fca_node_serials(config))
    missing_serials = sorted(serials - set(resolved_nodes.keys()))
    if not missing_serials:
        return True, lines, resolved_nodes, task_payloads
    if not provider_ext_id or not connection_ext_id:
        return False, [
            'FCA node onboarding requires hardware_provider_ext_id and connection_ext_id '
            f'for missing node serials: {", ".join(missing_serials)}'
        ], resolved_nodes, task_payloads

    nodes_path = _fca_provider_connection_path(provider_ext_id, connection_ext_id, 'nodes?$filter=')
    ok, message, payload, latency_ms = _fca_lifecycle_get(host, credential_ref, api_version, nodes_path)
    if not ok:
        return False, [f'FCA discovered node lookup failed: {message}'], resolved_nodes, task_payloads
    discovered = {
        _fca_node_match_key(item): item
        for item in _json_collection_items(payload)
        if isinstance(item, dict) and _fca_node_match_key(item)
    }
    lines.append(f'FCA discovered node lookup: {len(discovered)} item(s) ({latency_ms:>5.0f}ms)')

    tag_by_serial = {
        str(node.get('node_serial') or '').strip(): _fca_node_hostname(node)
        for node in _fca_config_nodes(config)
    }
    for serial in missing_serials:
        item = discovered.get(serial)
        if not item:
            return False, [*lines, f'FCA discovered node not found for serial: {serial}'], resolved_nodes, task_payloads
        submit_payload = {
            'extId': item.get('extId'),
            'vendor': str(item.get('manufacturer') or item.get('vendor') or config.get('hardware_provider_vendor') or 'Dell').split()[0],
            'hardwareProviderConnectionExtId': connection_ext_id,
            'uniqueIdentifierField': str(item.get('uniqueIdentifierType') or 'SERIAL'),
            'uniqueIdentifierValue': serial,
            'userTags': [tag_by_serial.get(serial) or serial],
        }
        ok, message, response_payload, latency_ms = _fca_lifecycle_request(
            host, credential_ref, api_version, 'POST', 'config/nodes', submit_payload,
        )
        task_payloads.append(response_payload if isinstance(response_payload, dict) else {})
        if not ok:
            return False, [*lines, f'FCA node onboarding failed for {serial}: {message}'], resolved_nodes, task_payloads
        lines.append(f'FCA node onboarding submitted for {serial}: {message} ({latency_ms:>5.0f}ms)')
        task_ext_id = _fca_response_ext_id(response_payload)
        if task_ext_id:
            task_ok, task_lines, task_payload = _fca_poll_prism_task(host, credential_ref, task_ext_id)
            task_payloads.append(task_payload)
            lines.extend(task_lines)
            if not task_ok:
                return False, lines, resolved_nodes, task_payloads

    ok, lookup_lines, resolved_nodes = _fca_resolve_onboarded_nodes(host, credential_ref, api_version, config)
    lines.extend(lookup_lines)
    if not ok:
        return False, lines, resolved_nodes, task_payloads
    still_missing = sorted(serials - set(resolved_nodes.keys()))
    if still_missing:
        return False, [*lines, f'FCA onboarded node lookup still missing: {", ".join(still_missing)}'], resolved_nodes, task_payloads
    return True, lines, resolved_nodes, task_payloads


def _fca_response_ext_id(payload: object) -> str:
    if not isinstance(payload, dict):
        return ''
    for key in ('extId', 'taskExtId', 'taskUuid', 'uuid', 'id'):
        value = payload.get(key)
        if value:
            return str(value)
    data = payload.get('data')
    if isinstance(data, dict):
        for key in ('extId', 'taskExtId', 'taskUuid', 'uuid', 'id'):
            value = data.get(key)
            if value:
                return str(value)
    return ''


def _fca_response_status_path(config: dict, payload: object) -> str:
    if isinstance(payload, dict):
        for key in ('statusPath', 'status_path', 'statusUrl', 'status_url'):
            value = payload.get(key)
            if value:
                text = str(value)
                marker = '/api/lifecycle/'
                if marker in text:
                    return text.split(marker, 1)[1].split('/', 1)[1]
                return text.lstrip('/')
    template = _fca_status_path_template(config)
    ext_id = _fca_response_ext_id(payload)
    if template and ext_id:
        return template.format(extId=urllib.parse.quote(ext_id), taskExtId=urllib.parse.quote(ext_id))
    return ''


def _fca_workflow_status_path(workflow: str, config: dict, payload: object) -> str:
    explicit = _fca_response_status_path(config, payload)
    if explicit:
        return explicit
    template = _fca_default_status_path_template(workflow)
    ext_id = _fca_response_ext_id(payload)
    if template and ext_id:
        return template.format(extId=urllib.parse.quote(ext_id, safe=''), taskExtId=urllib.parse.quote(ext_id, safe=''))
    return ''


def _fca_status_value(payload: object) -> str:
    if not isinstance(payload, dict):
        return ''
    candidates = [
        payload.get('status'),
        payload.get('state'),
        payload.get('phase'),
        payload.get('lifecycleState'),
    ]
    data = payload.get('data')
    if isinstance(data, dict):
        candidates.extend([data.get('status'), data.get('state'), data.get('phase'), data.get('lifecycleState')])
    for candidate in candidates:
        if isinstance(candidate, dict):
            value = candidate.get('state') or candidate.get('status') or candidate.get('phase')
            if value:
                return str(value)
        if candidate:
            return str(candidate)
    return ''


def _fca_status_document(payload: object) -> dict:
    if not isinstance(payload, dict):
        return {}
    data = payload.get('data')
    return data if isinstance(data, dict) else payload


def _fca_sanitize_status_text(value: object) -> str:
    text = str(value or '').strip()
    text = re.sub(r'\b(?:\d{1,3}\.){3}\d{1,3}\b', '<ip>', text)
    text = re.sub(
        r'\b[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\b',
        '<id>',
        text,
        flags=re.IGNORECASE,
    )
    return text


def _fca_phase_percentage(value: object) -> int | None:
    try:
        if value is None or value == '':
            return None
        return int(float(str(value)))
    except (TypeError, ValueError):
        return None


def _fca_phase_state(value: object) -> str:
    if isinstance(value, dict):
        value = value.get('state') or value.get('status') or value.get('phase')
    return _fca_sanitize_status_text(value)


def _fca_phase_name(value: object) -> str:
    return _fca_sanitize_status_text(value) or 'Unnamed phase'


def _fca_first_present(mapping: dict, *keys: str) -> object:
    for key in keys:
        if key in mapping and mapping[key] is not None:
            return mapping[key]
    return None


def _fca_subtask_summaries(progress_items: object) -> list[dict]:
    summaries: list[dict] = []
    if not isinstance(progress_items, list):
        return summaries
    for progress in progress_items:
        if not isinstance(progress, dict):
            continue
        subtasks = progress.get('subTasks') or progress.get('subtasks') or []
        if not isinstance(subtasks, list):
            continue
        for subtask in subtasks:
            if not isinstance(subtask, dict):
                continue
            messages = subtask.get('messages') or subtask.get('message') or []
            if isinstance(messages, str):
                messages = [messages]
            elif not isinstance(messages, list):
                messages = []
            cleaned_messages = [
                _fca_sanitize_status_text(message)
                for message in messages
                if _fca_sanitize_status_text(message)
            ]
            summaries.append({
                'name': _fca_phase_name(subtask.get('name') or subtask.get('displayName')),
                'state': _fca_phase_state(subtask.get('status') or subtask.get('state')),
                'percentage': _fca_phase_percentage(_fca_first_present(subtask, 'progressPercentage', 'percentage')),
                'messages': cleaned_messages[-3:],
            })
    return summaries


def _fca_workflow_status_summary(payload: object) -> dict:
    document = _fca_status_document(payload)
    status = document.get('status') if isinstance(document, dict) else {}
    phases = status.get('phases') if isinstance(status, dict) else document.get('phases') if isinstance(document, dict) else []
    if not isinstance(phases, list):
        phases = []

    phase_summaries: list[dict] = []
    failed_phase: dict | None = None
    failed_subtask: dict | None = None
    for phase in phases:
        if not isinstance(phase, dict):
            continue
        summary = {
            'name': _fca_phase_name(phase.get('name') or phase.get('displayName')),
            'state': _fca_phase_state(phase.get('state') or phase.get('status')),
            'percentage': _fca_phase_percentage(_fca_first_present(phase, 'percentage', 'progressPercentage')),
            'subTasks': _fca_subtask_summaries(phase.get('progress')),
        }
        phase_summaries.append(summary)
        if summary['state'].lower() in FCA_TERMINAL_FAILED_STATES and failed_phase is None:
            failed_phase = summary
        if failed_subtask is None:
            failed_subtask = next(
                (
                    subtask for subtask in summary['subTasks']
                    if str(subtask.get('state') or '').lower() in FCA_TERMINAL_FAILED_STATES
                ),
                None,
            )

    phase_line_parts = []
    for phase in phase_summaries:
        pct = phase.get('percentage')
        suffix = f' {pct}%' if pct is not None else ''
        phase_line_parts.append(f"{phase['name']} {phase['state'] or 'unknown'}{suffix}".strip())

    failure_reason = ''
    if failed_phase:
        pct = failed_phase.get('percentage')
        failure_reason = f"{failed_phase['name']} failed"
        if pct is not None:
            failure_reason += f' at {pct}%'
    if failed_subtask:
        pct = failed_subtask.get('percentage')
        subtask_reason = f"{failed_subtask['name']} failed"
        if pct is not None:
            subtask_reason += f' at {pct}%'
        failure_reason = f'{failure_reason}; {subtask_reason}' if failure_reason else subtask_reason
        messages = failed_subtask.get('messages') or []
        if messages:
            failure_reason += f"; last messages: {'; '.join(messages)}"

    return {
        'state': _fca_status_value(payload),
        'phases': phase_summaries,
        'phaseLine': '; '.join(phase_line_parts),
        'phaseSignature': json.dumps(phase_summaries, sort_keys=True),
        'failureReason': failure_reason,
    }


def _fca_public_diagnostics(diagnostics: dict) -> dict:
    allowed = {
        'fcaSubmitPath',
        'fcaWorkflow',
        'fcaStatusPath',
        'fcaStatusPollAttempts',
        'fcaStatusPollIntervalSeconds',
        'fcaLastObservedStatus',
        'fcaLastStatusSummary',
        'fcaStatusPollingExpired',
        'fcaTerminalFailureReason',
    }
    public = {key: diagnostics[key] for key in allowed if key in diagnostics}
    summary = public.get('fcaLastStatusSummary')
    if isinstance(summary, dict):
        public['fcaLastStatusSummary'] = {
            key: value for key, value in summary.items()
            if key != 'phaseSignature'
        }
    return public


def _execute_standalone_fca_lifecycle(workflow: str, config: dict) -> tuple[bool, list[str], dict]:
    lines: list[str] = []
    diagnostics: dict = {}
    host = str(config.get('fca_ip') or '').strip()
    credential_ref = str(config.get('fca_credential') or '').strip()
    api_version, api_error = _fca_api_version(config)
    if api_error:
        return False, [api_error], diagnostics
    submit_path = _fca_submit_path(workflow, config)
    if not submit_path:
        return False, ['Standalone FCA submit path is not configured'], diagnostics
    resolved_nodes: dict[str, dict] = {}
    if workflow == 'cluster-create-standalone-fca' and _fca_payload_override(config) is None:
        ok, image_lines, config = _fca_hydrate_cluster_image_ext_ids(host, credential_ref, api_version, config)
        lines.extend(image_lines)
        if not ok:
            return False, lines, diagnostics
        ok, resolve_lines, resolved_nodes = _fca_resolve_onboarded_nodes(host, credential_ref, api_version, config)
        lines.extend(resolve_lines)
        diagnostics['fcaResolvedNodes'] = sorted(resolved_nodes.keys())
        if not ok:
            return False, lines, diagnostics
        ok, onboard_lines, resolved_nodes, task_payloads = _fca_onboard_discovered_nodes(
            host, credential_ref, api_version, config, resolved_nodes,
        )
        lines.extend(onboard_lines)
        diagnostics['fcaOnboardingTaskResponses'] = task_payloads
        diagnostics['fcaResolvedNodes'] = sorted(resolved_nodes.keys())
        if not ok:
            return False, lines, diagnostics
        payload = _fca_build_cluster_workflow_payload(config, resolved_nodes)
        payload_errors = _fca_validate_cluster_workflow_payload(payload)
        if payload_errors:
            return False, [*lines, *payload_errors], diagnostics
    else:
        payload = _build_standalone_fca_payload(workflow, config)
    diagnostics['fcaSubmitPath'] = submit_path
    diagnostics['fcaWorkflow'] = workflow
    lines.append(f'Submitting standalone FCA Lifecycle request: POST /api/lifecycle/{api_version}/{submit_path.lstrip("/")}')
    ok, message, response_payload, latency_ms = _fca_lifecycle_request(
        host, credential_ref, api_version, 'POST', submit_path, payload,
    )
    diagnostics['fcaSubmitResponse'] = response_payload
    if not ok:
        return False, [*lines, f'FCA submit failed: {message}'], diagnostics
    lines.append(f'FCA submit accepted: {message} ({latency_ms:>5.0f}ms)')

    status_path = _fca_workflow_status_path(workflow, config, response_payload)
    if not status_path:
        lines.append('No FCA status endpoint was returned or configured; treating accepted submission as successful handoff.')
        return True, lines, diagnostics

    diagnostics['fcaStatusPath'] = status_path
    poll_attempts, poll_interval_seconds = _fca_status_poll_settings(config)
    diagnostics['fcaStatusPollAttempts'] = poll_attempts
    diagnostics['fcaStatusPollIntervalSeconds'] = poll_interval_seconds
    last_phase_signature = ''
    display_status = 'unknown'
    for attempt in range(1, poll_attempts + 1):
        if poll_interval_seconds:
            time.sleep(poll_interval_seconds)
        ok, message, status_payload, latency_ms = _fca_lifecycle_get(host, credential_ref, api_version, status_path)
        if not ok:
            return False, [*lines, f'FCA status poll failed: {message}'], diagnostics
        status_summary = _fca_workflow_status_summary(status_payload)
        diagnostics['fcaLastStatusSummary'] = status_summary
        status_value = status_summary.get('state') or ''
        display_status = status_value or 'unknown'
        diagnostics['fcaLastObservedStatus'] = display_status
        lines.append(f'FCA status poll {attempt:02d}: {display_status} ({latency_ms:>5.0f}ms)')
        phase_line = status_summary.get('phaseLine') or ''
        phase_signature = status_summary.get('phaseSignature') or ''
        if phase_line and phase_signature != last_phase_signature:
            lines.append(f'FCA phases: {phase_line}')
            last_phase_signature = phase_signature
        failure_reason = status_summary.get('failureReason') or ''
        if failure_reason:
            diagnostics['fcaTerminalFailureReason'] = failure_reason
        normalized = display_status.lower()
        if normalized in FCA_TERMINAL_SUCCESS_STATES:
            return True, lines, diagnostics
        if normalized in FCA_TERMINAL_FAILED_STATES:
            if failure_reason:
                lines.append(f'FCA terminal failure reason: {failure_reason}')
            return False, lines, diagnostics
    diagnostics['fcaStatusPollingExpired'] = True
    watched_seconds = poll_attempts * poll_interval_seconds
    return True, [
        *lines,
        (
            f'FCA status still {display_status} after {poll_attempts} polls'
            f' ({watched_seconds:.0f} seconds); treating accepted Lifecycle submission as successful handoff.'
        ),
    ], diagnostics


def _run_standalone_fca_lifecycle_preflight(workflow: str, config: dict) -> tuple[list[str], int, int]:
    lines: list[str] = []
    passed = 0
    failed = 0
    host = str(config.get('fca_ip') or '').strip()
    credential_ref = str(config.get('fca_credential') or '').strip()
    api_version, api_error = _fca_api_version(config)
    if api_error:
        lines.append(f'[FAIL] {api_error}: {api_version}')
        return lines, passed, failed + 1
    if not host or not credential_ref:
        return lines, passed, failed

    checks = [
        ('hardware providers', 'config/hardware-providers'),
        ('nodes', 'config/nodes?$page=0&$limit=100&$filter=isOnboarded%20eq%20true&$orderby=createdTime%20asc'),
        ('AOS images', "config/images?$page=0&$limit=100&$filter=type%20eq%20Lifecycle.Config.ImageType%27AOS%27&$orderby=name"),
        ('hypervisor images', "config/images?$page=0&$limit=100&$filter=type%20eq%20Lifecycle.Config.ImageType%27AHV%27&$orderby=name"),
        ('workflows', 'config/workflows?$page=0&$limit=20&$orderby=startedTime%20desc'),
    ]
    payloads: dict[str, object] = {}
    for label, path in checks:
        ok, message, payload, latency_ms = _fca_lifecycle_get(host, credential_ref, api_version, path)
        if ok:
            payloads[label] = payload
            lines.append(f'[PASS] FCA Lifecycle {label:<18}: {_json_collection_count(payload)} item(s) ({latency_ms:>5.0f}ms)')
            passed += 1
        else:
            lines.append(f'[FAIL] FCA Lifecycle {label:<18}: {message}')
            failed += 1

    provider_ext_id = str(config.get('hardware_provider_ext_id') or '').strip()
    provider_name = str(config.get('hardware_provider_name') or '').strip()
    provider_ok, provider_label = _find_ext_id(payloads.get('hardware providers'), provider_ext_id, provider_name)
    resolved_provider_ext_id = provider_ext_id or (provider_label if provider_ok else '')
    if provider_ext_id or provider_name:
        if provider_ok:
            lines.append(f'[PASS] Hardware provider matched : {provider_label}')
            passed += 1
        else:
            lines.append(f'[FAIL] Hardware provider not found: {provider_label}')
            failed += 1

    connection_ext_id = str(config.get('connection_ext_id') or '').strip()
    if resolved_provider_ext_id and connection_ext_id:
        ok, message, payload, latency_ms = _fca_lifecycle_get(
            host,
            credential_ref,
            api_version,
            f'config/hardware-providers/{urllib.parse.quote(resolved_provider_ext_id)}/connections',
        )
        if ok:
            connection_ok, _ = _find_ext_id(payload, connection_ext_id)
            if connection_ok:
                lines.append(f'[PASS] Hardware provider connection matched: {connection_ext_id} ({latency_ms:>5.0f}ms)')
                passed += 1
            else:
                lines.append(f'[FAIL] Hardware provider connection not found: {connection_ext_id}')
                failed += 1
        else:
            lines.append(f'[FAIL] Hardware provider connections request failed: {message}')
            failed += 1

    hydrated_config = dict(config)
    for image_key, label, payload_key, _path in STANDALONE_FCA_IMAGE_CHECKS:
        image_ext_id = str(config.get(image_key) or '').strip()
        if image_ext_id:
            image_ok, _ = _find_ext_id(payloads.get(payload_key), image_ext_id)
            if image_ok:
                lines.append(f'[PASS] {label} matched       : {image_ext_id}')
                passed += 1
            else:
                lines.append(f'[FAIL] {label} not found    : {image_ext_id}')
                failed += 1
        elif workflow == 'cluster-create-standalone-fca':
            inferred_ext_id, detail = _fca_single_image_ext_id(payloads.get(payload_key), label)
            if inferred_ext_id:
                hydrated_config[image_key] = inferred_ext_id
                lines.append(f'[PASS] {label} inferred      : {detail}')
                passed += 1
            elif payload_key in payloads:
                lines.append(f'[FAIL] FCA {detail}')
                failed += 1

    if resolved_provider_ext_id and connection_ext_id and _fca_node_serials(config):
        ok, message, payload, latency_ms = _fca_lifecycle_get(
            host,
            credential_ref,
            api_version,
            _fca_provider_connection_path(resolved_provider_ext_id, connection_ext_id, 'nodes?$filter='),
        )
        if ok:
            discovered = {_fca_node_match_key(item) for item in _json_collection_items(payload) if isinstance(item, dict)}
            configured = set(_fca_node_serials(config))
            matched = len(configured & discovered)
            lines.append(f'[PASS] FCA discovered nodes     : {matched}/{len(configured)} configured serial(s) ({latency_ms:>5.0f}ms)')
            passed += 1
        else:
            lines.append(f'[FAIL] FCA discovered node lookup failed: {message}')
            failed += 1

    if workflow == 'cluster-create-standalone-fca' and _fca_payload_override(config) is None:
        resolved_nodes = {
            _fca_node_match_key(item): item
            for item in _json_collection_items(payloads.get('nodes'))
            if isinstance(item, dict) and _fca_node_match_key(item)
        }
        payload = _fca_build_cluster_workflow_payload(hydrated_config, resolved_nodes)
        payload_errors = _fca_validate_cluster_workflow_payload(payload)
        if payload_errors:
            for error in payload_errors:
                lines.append(f'[FAIL] {error}')
                failed += 1
        else:
            lines.append('[PASS] FCA cluster workflow payload is complete')
            passed += 1

    lines.append('[INFO] Standalone FCA dry-run is read-only; Run Workflow submits Lifecycle requests only after explicit acknowledgement.')
    return lines, passed, failed


def _normalize_ztf_config_keys(workflow: str, config: dict) -> tuple[dict, bool]:
    """Map legacy Orchestrator configs to upstream ZTF keys."""
    changed = False
    normalized = dict(config)
    if workflow in PC_IP_WORKFLOWS and 'pc_ip' not in config and config.get('fc_ip'):
        normalized['pc_ip'] = normalized.pop('fc_ip')
        changed = True
    if workflow == 'cluster-create':
        if 'ztf_orchestrator' in normalized:
            normalized.pop('ztf_orchestrator', None)
            changed = True
        if 'foundation_central_target' in normalized:
            normalized.pop('foundation_central_target', None)
            changed = True
        network_key_map = {
            'name_servers_list': 'dns_servers',
            'ntp_servers_list': 'ntp_servers',
            'dns_servers': 'dns_servers',
            'ntp_servers': 'ntp_servers',
        }
        common_network_settings = normalized.get('common_network_settings')
        if not isinstance(common_network_settings, dict):
            common_network_settings = {}
        else:
            common_network_settings = dict(common_network_settings)
        for old_key, new_key in network_key_map.items():
            if old_key != new_key and old_key in common_network_settings and new_key not in common_network_settings:
                common_network_settings[new_key] = common_network_settings.pop(old_key)
                changed = True
        for old_key, new_key in network_key_map.items():
            if old_key in normalized and new_key not in common_network_settings:
                common_network_settings[new_key] = normalized.pop(old_key)
                changed = True
        create_clusters_source = normalized.get('create_clusters')
        if not isinstance(create_clusters_source, list) and isinstance(normalized.get('clusters'), list):
            create_clusters_source = normalized.pop('clusters')
            changed = True
        node_key_map = {
            'serial': 'node_serial',
            'nodeSerial': 'node_serial',
            'node_serial': 'node_serial',
        }
        if isinstance(create_clusters_source, list):
            create_clusters = []
            for cluster in create_clusters_source:
                if not isinstance(cluster, dict):
                    create_clusters.append(cluster)
                    continue
                cluster_copy = dict(cluster)
                for old_key, new_key in network_key_map.items():
                    if old_key in cluster_copy and new_key not in common_network_settings:
                        common_network_settings[new_key] = cluster_copy.pop(old_key)
                        changed = True
                if 'nodes_list' not in cluster_copy and 'nodes' in cluster_copy:
                    cluster_copy['nodes_list'] = cluster_copy.pop('nodes')
                    changed = True
                nodes_list = cluster_copy.get('nodes_list')
                if isinstance(nodes_list, list):
                    normalized_nodes = []
                    for node in nodes_list:
                        if not isinstance(node, dict):
                            normalized_nodes.append(node)
                            continue
                        node_copy = dict(node)
                        for old_key, new_key in node_key_map.items():
                            if old_key != new_key and old_key in node_copy and new_key not in node_copy:
                                node_copy[new_key] = node_copy.pop(old_key)
                                changed = True
                        normalized_nodes.append(node_copy)
                    cluster_copy['nodes_list'] = normalized_nodes
                create_clusters.append(cluster_copy)
            normalized['create_clusters'] = create_clusters
        if normalized.get('common_network_settings') != common_network_settings:
            normalized['common_network_settings'] = common_network_settings
            changed = True
    return normalized, changed


def _normalize_ztf_config_content(workflow: str, config_content: str) -> tuple[str, bool]:
    """Return YAML content with pc_ip if a legacy fc_ip-only file was supplied."""
    try:
        parsed = yaml.safe_load(config_content) or {}
    except yaml.YAMLError:
        return config_content, False
    if not isinstance(parsed, dict):
        return config_content, False
    normalized, changed = _normalize_ztf_config_keys(workflow, parsed)
    if not changed:
        return config_content, False
    return yaml.safe_dump(normalized, sort_keys=False), True

ALLOWED_SETTINGS_KEYS = {
    'ztfPath', 'ztf1Enabled', 'ztf2Enabled', 'ztf2Path', 'ztf2Command',
    'ztf2ProjectDir', 'nkpPath', 'pythonPath', 'configDir', 'repoUrl',
    'nkpRepoUrl', 'webhookUrl',
    'activeProfileId', 'connectionProfiles', 'approvalRequiredWorkflows',
}

# ─── Feature engines (lazy-initialised in _init_engines) ─────────────────────

from scheduler    import ScheduleEngine
from parallel_exec import ParallelEngine
from approvals    import ApprovalManager

_schedule_engine:  ScheduleEngine  | None = None
_parallel_engine:  ParallelEngine  | None = None
_approval_manager: ApprovalManager | None = None

def _init_engines():
    global _schedule_engine, _parallel_engine, _approval_manager
    if _schedule_engine and _parallel_engine and _approval_manager:
        return

    def _sched_run_callback(schedule: dict) -> str:
        """Execute a scheduled workflow via subprocess; return 'success'/'failed'."""
        import time as _t
        settings    = get_settings()
        ztf_path    = settings['ztfPath']
        python_path = settings['pythonPath']
        configs_dir = get_configs_dir()

        workflow       = schedule.get('workflow') or ''
        script         = schedule.get('script') or ''
        config_content = schedule.get('configContent') or ''
        config_file    = schedule.get('configFile') or ''

        standalone_error = _standalone_fca_execution_error(workflow or '', config_content)
        if workflow in STANDALONE_FCA_WORKFLOWS or standalone_error:
            rc = -1
            status = 'failed'
            entry = {
                'id':         str(int(_t.time() * 1000)),
                'workflow':   workflow or script,
                'type':       'schedule',
                'command':    '',
                'status':     status,
                'returnCode': rc,
                'timestamp':  datetime.datetime.now(datetime.timezone.utc).isoformat(),
                'user':       'scheduler',
                'configFile': config_file,
                'output':     standalone_error or STANDALONE_FCA_UNSUPPORTED_MESSAGE,
            }
            hist = read_json(HISTORY_FILE, [])
            hist.insert(0, entry)
            write_json(HISTORY_FILE, hist[:1000])
            _fire_configured_webhook(workflow or script, status, rc, 'scheduler', entry['id'])
            return status

        approval_error = _approval_automation_error(workflow)
        if approval_error:
            rc = -1
            status = 'failed'
            entry = {
                'id':         str(int(_t.time() * 1000)),
                'workflow':   workflow or script,
                'type':       'schedule',
                'command':    '',
                'status':     status,
                'returnCode': rc,
                'timestamp':  datetime.datetime.now(datetime.timezone.utc).isoformat(),
                'user':       'scheduler',
                'configFile': config_file,
                'output':     approval_error,
            }
            hist = read_json(HISTORY_FILE, [])
            hist.insert(0, entry)
            write_json(HISTORY_FILE, hist[:1000])
            _fire_configured_webhook(workflow or script, status, rc, 'scheduler', entry['id'], 'schedule')
            return status

        incompatible = _ztf_incompatible_error(ztf_path)
        if incompatible:
            rc = -1
            status = 'failed'
            entry = {
                'id':         str(int(_t.time() * 1000)),
                'workflow':   workflow or script,
                'type':       'schedule',
                'command':    '',
                'status':     status,
                'returnCode': rc,
                'timestamp':  datetime.datetime.now(datetime.timezone.utc).isoformat(),
                'user':       'scheduler',
                'configFile': config_file,
                'output':     incompatible[0]['error'],
            }
            hist = read_json(HISTORY_FILE, [])
            hist.insert(0, entry)
            write_json(HISTORY_FILE, hist[:1000])
            _fire_configured_webhook(workflow or script, status, rc, 'scheduler', entry['id'])
            return status

        import tempfile
        tf_path = None
        if config_content:
            standalone_error = _standalone_fca_execution_error(workflow or '', config_content)
            if standalone_error:
                rc = -1
                status = 'failed'
                entry = {
                    'id':         str(int(_t.time() * 1000)),
                    'workflow':   workflow or script,
                    'type':       'schedule',
                    'command':    '',
                    'status':     status,
                    'returnCode': rc,
                    'timestamp':  datetime.datetime.now(datetime.timezone.utc).isoformat(),
                    'user':       'scheduler',
                    'configFile': config_file,
                    'output':     standalone_error,
                }
                hist = read_json(HISTORY_FILE, [])
                hist.insert(0, entry)
                write_json(HISTORY_FILE, hist[:1000])
                _fire_configured_webhook(workflow or script, status, rc, 'scheduler', entry['id'])
                return status
            config_content, _ = _normalize_ztf_config_content(workflow or '', config_content)
            with tempfile.NamedTemporaryFile(
                mode='w', suffix='.yml', dir=str(configs_dir),
                delete=False, prefix='sched_'
            ) as tf:
                tf.write(config_content)
                tf_path = tf.name
        elif config_file:
            config_path = safe_config_path(config_file, configs_dir)
            if config_path is None or not config_path.exists():
                rc = -1
                cmd = [python_path, _ztf_main_arg(ztf_path)]
                status = 'failed'
                entry = {
                    'id':         str(int(_t.time() * 1000)),
                    'workflow':   workflow or script,
                    'type':       'schedule',
                    'command':    ' '.join(cmd),
                    'status':     status,
                    'returnCode': rc,
                    'timestamp':  datetime.datetime.now(datetime.timezone.utc).isoformat(),
                    'user':       'scheduler',
                    'configFile': config_file,
                }
                hist = read_json(HISTORY_FILE, [])
                hist.insert(0, entry)
                write_json(HISTORY_FILE, hist[:1000])
                _fire_configured_webhook(workflow or script, status, rc, 'scheduler', entry['id'])
                return status
            tf_path = str(config_path)

        cmd = [python_path, _ztf_main_arg(ztf_path)]
        if workflow:
            cmd.append(f'--workflow={workflow}')
        if script:
            cmd += ['--script', script]
        if tf_path:
            cmd += ['-f', tf_path]

        try:
            r = subprocess.run(
                cmd, cwd=ztf_path, capture_output=True, text=True,
                timeout=EXEC_TIMEOUT
            )
            rc = r.returncode
        except subprocess.TimeoutExpired:
            rc = -1
        except Exception:
            rc = -1
        finally:
            if config_content and tf_path:
                try:
                    Path(tf_path).unlink(missing_ok=True)
                except Exception:
                    pass

        status = 'success' if rc == 0 else 'failed'
        # Record in history
        entry = {
            'id':        str(int(_t.time() * 1000)),
            'workflow':  workflow or script,
            'type':      'schedule',
            'command':   ' '.join(cmd),
            'status':    status,
            'returnCode': rc,
            'timestamp': datetime.datetime.now(datetime.timezone.utc).isoformat(),
            'user':      'scheduler',
            'configFile': config_file,
        }
        hist = read_json(HISTORY_FILE, [])
        hist.insert(0, entry)
        write_json(HISTORY_FILE, hist[:1000])
        _fire_configured_webhook(workflow or script, status, rc, 'scheduler',
                                 entry['id'])
        return status

    _schedule_engine  = ScheduleEngine(
        SCHEDULES_FILE,
        _sched_run_callback,
        load_callback=lambda: read_json(SCHEDULES_FILE, []),
        save_callback=lambda schedules: write_json(SCHEDULES_FILE, schedules),
    )
    _parallel_engine  = ParallelEngine(
        PARALLEL_FILE,
        EXEC_TIMEOUT,
        load_callback=lambda: read_json(PARALLEL_FILE, []),
        save_callback=lambda runs: write_json(PARALLEL_FILE, runs),
    )
    _approval_manager = ApprovalManager(
        APPROVALS_FILE,
        _fire_configured_webhook,
        load_callback=lambda: read_json(APPROVALS_FILE, []),
        save_callback=lambda approvals: write_json(APPROVALS_FILE, approvals),
    )
    _schedule_engine.start()

import atexit as _atexit
def _shutdown_engines():
    if _schedule_engine:
        _schedule_engine.shutdown()
_atexit.register(_shutdown_engines)


def _require_engines():
    """Initialise feature engines for test clients or WSGI imports."""
    if not (_schedule_engine and _parallel_engine and _approval_manager):
        _init_engines()


def _schedule_validation_error(data: dict, existing: dict | None = None) -> str:
    candidate = {**(existing or {}), **data}
    cron = str(candidate.get('cronExpr', '')).strip()
    if not cron or len(cron.split()) != 5:
        return 'cronExpr must be a valid 5-field cron expression'
    workflow = str(candidate.get('workflow', '')).strip()
    script = str(candidate.get('script', '')).strip()
    if workflow and workflow not in ALLOWED_WORKFLOWS:
        return 'Unknown workflow'
    approval_error = _approval_automation_error(workflow)
    if approval_error:
        return approval_error
    if script:
        _, script_error = _normalize_script_ids(_script_ids_from_payload(script))
        if script_error:
            return script_error
    if not workflow and not script:
        return 'workflow or script required'
    return ''

# ─── Concurrency lock ─────────────────────────────────────────────────────────

_RUNNING: set[str] = set()
_RUNNING_LOCK = threading.Lock()
_MAINTENANCE_LOCK = threading.RLock()
_MAINTENANCE = {
    'active': False,
    'reason': '',
    'startedAt': '',
    'startedBy': '',
}


def _maintenance_state() -> dict:
    with _MAINTENANCE_LOCK:
        return dict(_MAINTENANCE)


def _maintenance_active() -> bool:
    return bool(_maintenance_state().get('active'))


def _enter_maintenance(reason: str, user: str) -> bool:
    with _MAINTENANCE_LOCK:
        if _MAINTENANCE['active']:
            return False
        _MAINTENANCE.update({
            'active': True,
            'reason': reason,
            'startedAt': _now_iso(),
            'startedBy': user,
        })
        return True


def _exit_maintenance() -> None:
    with _MAINTENANCE_LOCK:
        _MAINTENANCE.update({
            'active': False,
            'reason': '',
            'startedAt': '',
            'startedBy': '',
        })


def _maintenance_error() -> tuple[dict, int]:
    state = _maintenance_state()
    reason = state.get('reason') or 'maintenance'
    return {
        'error': f'Execution queue is locked for {reason}',
        'maintenance': state,
    }, 503

# ─── User & session management ────────────────────────────────────────────────

ROLES = ('admin', 'operator', 'viewer')

def _load_users() -> list[dict]:
    return read_json(USERS_FILE, [])

def _save_users(users: list[dict]):
    write_json(USERS_FILE, users)

def _find_user(username: str) -> dict | None:
    return next((u for u in _load_users() if u['username'] == username), None)

def _ensure_default_admin():
    if _load_users():
        return
    password = secrets.token_hex(12)
    hashed   = bcrypt.hashpw(password.encode(), bcrypt.gensalt()).decode()
    _save_users([{
        'id':           str(uuid.uuid4()),
        'username':     'admin',
        'password_hash': hashed,
        'role':         'admin',
        'created_at':   datetime.datetime.now(datetime.timezone.utc).strftime('%Y-%m-%dT%H:%M:%S.%f') + 'Z',
    }])
    print('\n' + '=' * 60)
    print('  First run — default admin account created')
    print(f'  Username: admin')
    print(f'  Password: {password}')
    print('  Change this immediately via Settings > Users.')
    print('=' * 60 + '\n', flush=True)

# Session store: { token -> { username, role, expires: datetime } }
_SESSIONS: dict[str, dict] = {}
_SESSIONS_LOCK = threading.Lock()

def _create_session(username: str, role: str) -> str:
    token = secrets.token_hex(32)
    expires = datetime.datetime.now(datetime.timezone.utc) + datetime.timedelta(seconds=TOKEN_TTL)
    if hasattr(_storage, 'create_session'):
        _storage.create_session(token, username, role, expires)
        return token
    with _SESSIONS_LOCK:
        _SESSIONS[token] = {'username': username, 'role': role, 'expires': expires}
    return token

def _get_session(token: str) -> dict | None:
    if hasattr(_storage, 'get_session'):
        return _storage.get_session(token)
    with _SESSIONS_LOCK:
        session = _SESSIONS.get(token)
        if session and datetime.datetime.now(datetime.timezone.utc) < session['expires']:
            return session
        if session:
            del _SESSIONS[token]
    return None

def _invalidate_session(token: str):
    if hasattr(_storage, 'invalidate_session'):
        _storage.invalidate_session(token)
        return
    with _SESSIONS_LOCK:
        _SESSIONS.pop(token, None)

def _purge_expired():
    if hasattr(_storage, 'purge_expired_sessions'):
        _storage.purge_expired_sessions()
        return
    now = datetime.datetime.now(datetime.timezone.utc)
    with _SESSIONS_LOCK:
        expired = [t for t, s in _SESSIONS.items() if now >= s['expires']]
        for t in expired:
            del _SESSIONS[t]

# ─── Auth decorators ──────────────────────────────────────────────────────────

def _current_session() -> dict | None:
    auth = request.headers.get('Authorization', '')
    if auth.startswith('Bearer '):
        return _get_session(auth[7:])
    return None

def require_auth(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        session = _current_session()
        if not session:
            return jsonify({'error': 'Unauthorized'}), 401
        request.current_user = session
        return f(*args, **kwargs)
    return decorated

def require_role(*roles):
    def decorator(f):
        @wraps(f)
        def decorated(*args, **kwargs):
            session = _current_session()
            if not session:
                return jsonify({'error': 'Unauthorized'}), 401
            if session['role'] not in roles:
                return jsonify({'error': 'Forbidden'}), 403
            request.current_user = session
            return f(*args, **kwargs)
        return decorated
    return decorator

# ─── Request / response hooks ─────────────────────────────────────────────────

@app.before_request
def check_body_size():
    if request.path == '/api/nkp/binaries/upload':
        max_body = NKP_BINARY_MAX_UPLOAD
    elif request.path == '/api/appliance/updates/import-package':
        max_body = UPDATE_PACKAGE_MAX_UPLOAD
    else:
        max_body = MAX_BODY
    if request.content_length and request.content_length > max_body:
        return jsonify({'error': 'Request body too large'}), 413

@app.before_request
def log_request():
    _purge_expired()
    session = _current_session()
    path = request.full_path.rstrip('?')
    action = f'{request.method} {path}'
    log.info(action,
             extra={'event': 'http_request',
                    'action': action,
                    'method': request.method,
                    'path': request.path,
                    'query': request.query_string.decode('utf-8', errors='replace'),
                    'ip': request.remote_addr,
                    'user': session['username'] if session else 'anonymous'})

@app.after_request
def add_security_headers(resp):
    resp.headers['X-Content-Type-Options']  = 'nosniff'
    resp.headers['X-Frame-Options']         = 'DENY'
    resp.headers['Cache-Control']           = 'no-store'
    resp.headers['Permissions-Policy']      = 'geolocation=(), microphone=(), camera=()'
    resp.headers['Referrer-Policy']         = 'strict-origin-when-cross-origin'
    resp.headers['Content-Security-Policy'] = (
        "default-src 'self'; "
        "script-src 'self'; "
        "style-src 'self' 'unsafe-inline'; "
        "img-src 'self' data:; "
        "connect-src 'self'"
    )
    return resp

# ─── Helpers ──────────────────────────────────────────────────────────────────

def read_json(path: Path, default=None):
    fallback = default if default is not None else {}
    return _storage.read_json(path, fallback)

def write_json(path: Path, data):
    _storage.write_json(path, data)


def _git_metadata_value(args: list[str]) -> str:
    try:
        result = subprocess.run(
            ['git', *args],
            cwd=Path(__file__).resolve().parent,
            capture_output=True,
            text=True,
            timeout=2,
        )
    except (OSError, subprocess.SubprocessError):
        return ''
    if result.returncode != 0:
        return ''
    return result.stdout.strip()


def _latest_applied_orchestrator_update() -> dict:
    updates = read_json(APPLIANCE_UPDATES_FILE, [])
    if not isinstance(updates, list):
        return {}
    applied = [
        item for item in updates
        if isinstance(item, dict)
        and item.get('target') == 'ztf-orchestrator'
        and str(item.get('appliedAt') or '').strip()
    ]
    applied.sort(key=lambda item: str(item.get('appliedAt') or ''), reverse=True)
    latest = applied[0] if applied else {}
    if not latest:
        return {}
    return {
        'version': str(latest.get('version') or '').strip(),
        'sourceRef': str(latest.get('sourceRef') or '').strip(),
        'releaseUrl': str(latest.get('releaseUrl') or '').strip(),
        'packageId': str(latest.get('packageId') or latest.get('id') or '').strip(),
        'appliedAt': str(latest.get('appliedAt') or '').strip(),
    }


def _installed_build_metadata() -> dict:
    update = _latest_applied_orchestrator_update()
    source_ref = (
        os.environ.get('ZTF_SOURCE_REF', '').strip()
        or update.get('sourceRef', '')
        or _git_metadata_value(['describe', '--tags', '--always', '--dirty'])
    )
    commit = (
        os.environ.get('ZTF_BUILD_COMMIT', '').strip()
        or _git_metadata_value(['rev-parse', '--short=12', 'HEAD'])
    )
    package_id = (
        os.environ.get('ZTF_UPDATE_PACKAGE_ID', '').strip()
        or update.get('packageId', '')
    )
    version_tag = os.environ.get('ZTF_ORCHESTRATOR_VERSION', '').strip() or f'v{APP_VERSION}'
    identity_parts = [version_tag]
    if package_id:
        identity_parts.append(package_id)
    elif source_ref and source_ref != version_tag:
        identity_parts.append(source_ref)
    if commit and commit not in identity_parts:
        identity_parts.append(commit)
    return {
        'version': APP_VERSION,
        'versionTag': version_tag,
        'installedIdentity': ' / '.join(identity_parts),
        'sourceRef': source_ref,
        'commit': commit,
        'buildDate': os.environ.get('ZTF_BUILD_DATE', '').strip(),
        'containerImage': os.environ.get('ZTF_ORCHESTRATOR_IMAGE', '').strip(),
        'updatePackageId': package_id,
        'appliedUpdate': update,
    }


