@app.route('/api/settings/test-connection', methods=['POST'])
@require_role('admin', 'operator')
def test_connection_profile_target():
    data = request.json or {}
    target = str(data.get('target') or '').strip()
    profile = data.get('profile') or {}
    label, host, port, error = _connection_test_target(profile, target)
    if error:
        status_code = 400 if error in {'profile is required', 'unknown connection target'} else 200
        return jsonify({
            'ok': False,
            'target': target,
            'label': label or target,
            'host': host,
            'port': port,
            'message': error,
        }), status_code

    if target == 'prismCentral':
        prism_profile = profile.get('prismCentral') or {}
        credential_ref = (prism_profile.get('credentialRef') or '')
        scheme = _endpoint_scheme(prism_profile.get('endpoint') or '')
        ok, message, auth_latency_ms = _prism_central_login_check(host, int(port), credential_ref, scheme)
        return jsonify({
            'ok': ok,
            'target': target,
            'label': label,
            'host': host,
            'port': port,
            'latencyMs': round(auth_latency_ms, 1) if auth_latency_ms else None,
            'auth': True,
            'tlsVerified': False,
            'scheme': scheme,
            'message': message,
        })

    reachable, latency_ms = _tcp_check(host, int(port))
    return jsonify({
        'ok': reachable,
        'target': target,
        'label': label,
        'host': host,
        'port': port,
        'latencyMs': round(latency_ms, 1) if reachable else None,
        'message': (
            f'{label} reachable at {host}:{port}'
            if reachable else
            f'{label} is not reachable at {host}:{port}'
        ),
    })

# ─── System check ─────────────────────────────────────────────────────────────

@app.route('/api/system/check')
@require_role('admin', 'operator')
def system_check():
    settings    = get_settings()
    python_path = settings['pythonPath']
    ztf_path    = settings['ztfPath']
    nkp_path    = settings.get('nkpPath') or NKP_DEFAULT

    def run_check(name: str, cmd: list[str]) -> dict:
        try:
            r = subprocess.run(cmd, capture_output=True, text=True, timeout=10)
            return {'name': name, 'ok': r.returncode == 0, 'value': r.stdout.strip()}
        except Exception:
            return {'name': name, 'ok': False, 'value': 'check failed'}

    ztf_info = _ztf_detect(ztf_path)
    ztf2_info = _ztf2_detect(settings.get('ztf2Path') or ZTF2_DEFAULT, settings.get('ztf2Command') or ZTF2_COMMAND_DEFAULT)
    ztf_installed = bool(ztf_info.get('compatible'))
    ztf2_installed = bool(ztf2_info.get('compatible'))
    nkp_installed = _nkp_installed(nkp_path)
    nkp_binaries = _list_nkp_binaries()
    available_nkp_binaries = sum(1 for item in nkp_binaries if item.get('exists'))
    checks = [
        run_check('Python 3.9+', [python_path, '--version']),
        run_check('pip',          [python_path, '-m', 'pip', '--version']),
        run_check('git',          ['git', '--version']),
        {'name': 'ZTF Installed', 'ok': ztf_installed, 'value': ztf_info['message'] if ztf_info.get('installed') else ''},
        {'name': 'ZTF 2.x Plan/Apply', 'ok': ztf2_installed, 'value': ztf2_info['message']},
        {'name': 'NKP Framework', 'ok': True, 'value': 'found' if nkp_installed else 'not installed (optional)'},
        {
            'name': 'NKP Binaries',
            'ok': True,
            'value': f'{available_nkp_binaries}/{len(nkp_binaries)} available' if nkp_binaries else 'none registered (optional)',
        },
    ]
    if ztf_installed:
        # Use the same dynamic lookup as the install endpoint —
        # ZTF ships prod.txt not requirements.txt
        req_file = _ztf_requirements_file(ztf_path)
        checks.append({
            'name':  'Requirements File',
            'ok':    True,
            'value': req_file or 'not required - packaged install',
        })
    return jsonify({
        'checks': checks,
        'ztfInstalled': ztf_installed,
        'ztf': ztf_info,
        'ztf2Installed': ztf2_installed,
        'ztf2': {
            **ztf2_info,
            'enabled': bool(settings.get('ztf2Enabled', False)),
            'path': settings.get('ztf2Path') or ZTF2_DEFAULT,
            'command': settings.get('ztf2Command') or ZTF2_COMMAND_DEFAULT,
            'projectDir': settings.get('ztf2ProjectDir') or str(CONFIG_DIR / 'ztf2-projects' / 'default'),
        },
        'nkpInstalled': nkp_installed,
        'nkpBinaries': {'total': len(nkp_binaries), 'available': available_nkp_binaries},
    })

