@app.route('/api/native-foundation/phases/advancement-review', methods=['POST'])
@require_role('admin', 'operator', 'viewer')
def native_foundation_phase_advancement_review():
    data = request.json or {}
    requested_phase_id = str(data.get('phaseId') or data.get('requestedPhaseId') or '').strip()
    if not requested_phase_id:
        return jsonify({'error': 'Native Foundation phase advancement review requires phaseId'}), 400
    content = str(data.get('content') or data.get('configContent') or '')
    if not content.strip():
        return jsonify({'error': 'Native Foundation phase advancement review requires content'}), 400
    try:
        parsed = yaml.safe_load(content) or {}
    except yaml.YAMLError as exc:
        return jsonify({'error': f'YAML parse error: {exc}'}), 400
    if not isinstance(parsed, dict):
        return jsonify({'error': 'Native Foundation intent must be a YAML mapping'}), 400
    review = _native_foundation_phase_advancement_review(parsed, content, requested_phase_id)
    if review['status'] == 'failed':
        return jsonify(review), 400
    return jsonify(review), 200


