@app.route('/api/native-foundation/execution/review-job', methods=['POST'])
@require_role('admin', 'operator')
@limiter.limit('10 per minute')
def native_foundation_review_job():
    data = request.json or {}
    if _maintenance_active():
        body, status_code = _maintenance_error()
        return jsonify(body), status_code
    content = str(data.get('content') or data.get('configContent') or '')
    if not content.strip():
        return jsonify({'error': 'Native Foundation review job requires content'}), 400
    try:
        parsed = yaml.safe_load(content) or {}
    except yaml.YAMLError as exc:
        return jsonify({'error': f'YAML parse error: {exc}'}), 400
    if not isinstance(parsed, dict):
        return jsonify({'error': 'Native Foundation intent must be a YAML mapping'}), 400
    plan = _native_foundation_plan(parsed, content)
    if plan['status'] != 'valid':
        return jsonify({
            'status': 'invalid',
            'error': 'Native Foundation review job requires valid planning intent',
            'warnings': plan.get('warnings', []),
        }), 400
    current_user = getattr(request, 'current_user', {}).get('username', 'unknown')
    approval_id = str(data.get('approvalId') or data.get('approval_id') or '').strip()
    evidence_id = str(data.get('evidenceId') or data.get('evidence_id') or '').strip()
    job = _job_manager.submit({
        'framework': 'native-foundation',
        'type': 'native-foundation-review',
        'workflow': NATIVE_FOUNDATION_WORKFLOW,
        'configContent': content,
        'configFile': str(data.get('configFile') or 'native-foundation-deploy.yml').strip(),
        'phase': str(data.get('phase') or 'full_deployment').strip() or 'full_deployment',
        'approvalId': approval_id,
        'evidenceId': evidence_id,
        'trace': {
            'planId': plan.get('planId'),
            'intentSha256': plan.get('intentSha256'),
            'discoverySha256': plan.get('discoverySha256'),
            'approvalId': approval_id or None,
            'evidenceId': evidence_id or None,
            'readOnly': True,
            'mutatingActionsEnabled': False,
        },
    }, current_user)
    return jsonify(job), 202


