@app.route('/api/jobs', methods=['POST'])
@require_role('admin', 'operator')
@limiter.limit('10 per minute')
def submit_job():
    data = request.json or {}
    if _maintenance_active():
        body, status_code = _maintenance_error()
        return jsonify(body), status_code
    settings = get_settings()
    current_user = getattr(request, 'current_user', {}).get('username', 'unknown')
    if data.get('framework') == 'ztf2':
        runtime_error = _ztf2_runtime_error(settings)
        if runtime_error:
            body, status_code = runtime_error
            return jsonify(body), status_code
        action = str(data.get('ztf2Action') or data.get('action') or 'plan').strip().lower()
        if action not in ZTF2_ACTIONS:
            return jsonify({'error': 'ZTF 2.x action is not allowed'}), 400
        plan_id = str(data.get('planId') or uuid.uuid4()).strip()
        trace = _ztf2_plan_trace({**data, 'ztf2Action': action}, settings, plan_id)
        plan_path = str(_ztf2_project_dir(settings) / 'plans' / f'{plan_id}-plan.json')
        approval = None
        if action in ZTF2_APPROVAL_ACTIONS:
            source_plan_id = str(data.get('sourcePlanJobId') or data.get('planJobId') or '').strip()
            plan_job = _job_manager.get_job(source_plan_id, include_logs=False) if source_plan_id else None
            if not plan_job:
                return jsonify({'error': 'ZTF 2.x apply/destroy requires sourcePlanJobId for a successful plan job'}), 403
            plan_trace = dict(plan_job.get('trace') or {})
            trace.update({
                'planId': str(plan_trace.get('planId') or plan_id),
                'inputSha256': str(plan_trace.get('inputSha256') or ''),
                'globalSha256': str(plan_trace.get('globalSha256') or ''),
                'statePath': str(plan_trace.get('statePath') or ''),
            })
            approval_id = str(data.get('approvalId') or '').strip()
            approval = _approval_manager.get_approval(approval_id) if approval_id else None
            approval_error = _ztf2_approval_error(approval, plan_job, trace)
            if approval_error:
                return jsonify({'error': approval_error, 'approvalRequired': True}), 403
            plan_path = str(plan_trace.get('planPath') or plan_path)
        payload = {
            'framework': 'ztf2',
            'type': 'ztf2',
            'workflow': f'ztf2:{action}',
            'ztf2Action': action,
            'inputContent': data.get('inputContent') or data.get('configContent') or '',
            'globalContent': data.get('globalContent') or '',
            'inputFile': data.get('inputFile') or data.get('configFile') or 'input.yml',
            'globalFile': data.get('globalFile') or 'global.yml',
            'stateFile': data.get('stateFile') or 'state.yml',
            'planId': trace.get('planId') or plan_id,
            'planPath': plan_path,
            'approvalId': str(data.get('approvalId') or '').strip() or None,
            'trace': {**trace, 'planPath': plan_path},
        }
        job = _job_manager.submit(payload, current_user)
        if approval:
            _approval_manager.link_job(approval['id'], job['id'])
        return jsonify(job), 202
    workflow = data.get('workflow')
    script_ids, script_error = _normalize_script_ids(_script_ids_from_payload(data.get('script')))
    if script_error:
        return jsonify({'error': script_error}), 400
    destructive_error = _validate_destructive_script_ack(script_ids, data)
    if destructive_error:
        return jsonify({'error': destructive_error, 'destructiveAction': True}), 403
    script = ','.join(script_ids) if script_ids else None

    if workflow and workflow not in ALLOWED_WORKFLOWS:
        return jsonify({'error': 'Unknown workflow'}), 400
    if not workflow and not script:
        return jsonify({'error': 'workflow or script required'}), 400
    if workflow == NATIVE_FOUNDATION_WORKFLOW:
        content = str(data.get('configContent') or data.get('content') or '')
        try:
            native_config = yaml.safe_load(content) or {}
        except yaml.YAMLError as exc:
            return jsonify({'error': f'Native Foundation YAML parse error: {exc}'}), 400
        if not isinstance(native_config, dict):
            return jsonify({'error': 'Native Foundation intent must be a YAML mapping'}), 400
        plan = _native_foundation_plan(native_config, content)
        if plan.get('status') != 'valid':
            return jsonify({
                'error': 'Native Foundation deployment requires valid planning intent',
                'warnings': plan.get('warnings', []),
            }), 400
        gate_ok, gate_reasons = _native_foundation_dell_idrac_uat_execution_gate(native_config)
        if not gate_ok:
            return jsonify({
                'error': 'Native Foundation Dell iDRAC UAT deployment is not enabled',
                'requiredActions': gate_reasons,
            }), 403
        approval_error, approval = _validate_workflow_approval(data, settings)
        if approval_error:
            return jsonify({'error': approval_error, 'approvalRequired': True}), 403
        job = _job_manager.submit({
            'framework': 'native-foundation',
            'type': 'native-foundation-deployment-uat',
            'workflow': NATIVE_FOUNDATION_WORKFLOW,
            'configContent': content,
            'configFile': data.get('configFile') or 'native-foundation-deploy.yml',
            'phase': str(data.get('phase') or 'full_deployment').strip() or 'full_deployment',
            'approvalId': str(data.get('approvalId') or '').strip() or None,
            'evidenceId': str(data.get('evidenceId') or '').strip() or None,
            'trace': {
                'planId': plan.get('planId'),
                'intentSha256': plan.get('intentSha256'),
                'discoverySha256': plan.get('discoverySha256'),
                'approvalId': str(data.get('approvalId') or '').strip() or None,
                'evidenceId': str(data.get('evidenceId') or '').strip() or None,
                'readOnly': False,
                'mutatingActionsEnabled': True,
                'providerId': 'dell_idrac_redfish',
                'controlledUat': True,
            },
        }, current_user)
        if approval:
            _approval_manager.link_job(approval['id'], job['id'])
        return jsonify(job), 202
    standalone_fca_error = _validate_standalone_fca_ack(workflow, data)
    if standalone_fca_error:
        return jsonify({'error': standalone_fca_error, 'destructiveAction': True}), 403

    if workflow not in STANDALONE_FCA_WORKFLOWS:
        incompatible = _ztf_incompatible_error(settings['ztfPath'])
        if incompatible:
            body, status_code = incompatible
            return jsonify(body), status_code

    approval_error, approval = _validate_workflow_approval(data, settings)
    if approval_error:
        return jsonify({'error': approval_error, 'approvalRequired': True}), 403

    job = _job_manager.submit({
        'workflow': workflow,
        'script': script,
        'configContent': data.get('configContent'),
        'configFile': data.get('configFile'),
        'debug': bool(data.get('debug', False)),
        'riskAcknowledged': bool(data.get('riskAcknowledged', False)),
        'destructiveConfirmation': str(data.get('destructiveConfirmation') or '').strip(),
        'approvalId': str(data.get('approvalId') or '').strip() or None,
    }, current_user)
    if approval:
        _approval_manager.link_job(approval['id'], job['id'])
    return jsonify(job), 202


